-- ============================================================================
-- 034_pos_phase2.sql
-- ============================================================================
-- ============================================================================
-- 034_pos_phase2.sql — Module Supermarché, Phase 2: complète le POS selon le
-- cahier des charges (TVA, tickets en attente, annulation de ligne avec
-- autorisation, multi-paiement, reçus numérotés).
--
-- Décisions de modélisation :
--
-- * Les prix affichés en rayon sont TTC (usage retail en RDC) — la TVA est
--   donc EXTRAITE du total : tva = total × taux / (100 + taux), et
--   subtotal_cents devient le HT (total_cents reste le montant à payer,
--   inchangé pour les tickets existants). Le taux est par boutique
--   (merchants.pos_tva_rate_pct, 16% par défaut — taux RDC — modifiable).
--
-- * Les lignes annulées ne sont plus supprimées mais marquées 'voided' avec
--   qui/quand/pourquoi/qui-a-autorisé — le spec exige la traçabilité des
--   annulations, une ligne supprimée ne laisse aucune trace.
--
-- * pos_ticket_payments permet de combiner plusieurs modes sur un même
--   ticket (ex: partie espèces + reste en ScanLinkPay). payment_method sur
--   pos_tickets devient 'mixed' dans ce cas. Une ligne ScanLinkPay démarre
--   'pending' et passe 'confirmed' quand la payment_request liée est PAID —
--   le ticket n'est soldé que quand les paiements confirmés couvrent le
--   total.
--
-- * ticket_number : numérotation lisible par boutique (compteur
--   merchants.pos_ticket_seq incrémenté atomiquement par le backend),
--   pour les reçus — plus parlant qu'un UUID tronqué sur papier.
--
-- Run once in the Supabase SQL editor, same as previous migrations.
-- ============================================================================

ALTER TABLE merchants ADD COLUMN IF NOT EXISTS pos_tva_rate_pct NUMERIC(5,2) NOT NULL DEFAULT 16;
ALTER TABLE merchants ADD COLUMN IF NOT EXISTS pos_ticket_seq BIGINT NOT NULL DEFAULT 0;

ALTER TABLE pos_tickets ADD COLUMN IF NOT EXISTS ticket_number BIGINT;
ALTER TABLE pos_tickets ADD COLUMN IF NOT EXISTS is_held BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE pos_tickets ADD COLUMN IF NOT EXISTS hold_note VARCHAR(120);
ALTER TABLE pos_tickets ADD COLUMN IF NOT EXISTS tva_cents BIGINT NOT NULL DEFAULT 0;

ALTER TABLE pos_tickets DROP CONSTRAINT IF EXISTS pos_tickets_payment_method_check;
ALTER TABLE pos_tickets ADD CONSTRAINT pos_tickets_payment_method_check
  CHECK (payment_method IN ('cash', 'scanlinkpay', 'mixed'));

-- Backfill : numéroter les tickets existants dans l'ordre de création, puis
-- aligner le compteur de chaque boutique sur son max.
UPDATE pos_tickets t SET ticket_number = sub.rn
FROM (
  SELECT id, ROW_NUMBER() OVER (PARTITION BY merchant_id ORDER BY created_at) AS rn
  FROM pos_tickets
) sub
WHERE t.id = sub.id AND t.ticket_number IS NULL;

UPDATE merchants m SET pos_ticket_seq = COALESCE(
  (SELECT MAX(ticket_number) FROM pos_tickets WHERE merchant_id = m.id), 0
);

-- Numérotation atomique par boutique — le backend appelle cet RPC à la
-- création d'un ticket (pas de race possible entre deux caisses de la même
-- boutique). Les tickets annulés gardent leur numéro : les trous dans la
-- séquence sont normaux et attendus sur des reçus fiscaux.
CREATE OR REPLACE FUNCTION public.next_pos_ticket_number(p_merchant_id UUID)
RETURNS BIGINT LANGUAGE sql AS $$
  UPDATE merchants SET pos_ticket_seq = pos_ticket_seq + 1
  WHERE id = p_merchant_id RETURNING pos_ticket_seq;
$$;

ALTER TABLE pos_ticket_items ADD COLUMN IF NOT EXISTS status VARCHAR(20) NOT NULL DEFAULT 'active';
ALTER TABLE pos_ticket_items DROP CONSTRAINT IF EXISTS pos_ticket_items_status_check;
ALTER TABLE pos_ticket_items ADD CONSTRAINT pos_ticket_items_status_check
  CHECK (status IN ('active', 'voided'));
ALTER TABLE pos_ticket_items ADD COLUMN IF NOT EXISTS voided_by UUID REFERENCES auth.users(id);
ALTER TABLE pos_ticket_items ADD COLUMN IF NOT EXISTS void_authorized_by UUID REFERENCES auth.users(id);
ALTER TABLE pos_ticket_items ADD COLUMN IF NOT EXISTS voided_reason TEXT;
ALTER TABLE pos_ticket_items ADD COLUMN IF NOT EXISTS voided_at TIMESTAMPTZ;
-- Coût d'achat figé à la vente : la marge des stats reste juste même si le
-- prix d'achat du produit change ensuite.
ALTER TABLE pos_ticket_items ADD COLUMN IF NOT EXISTS cost_price_cents_snapshot BIGINT;

CREATE TABLE IF NOT EXISTS pos_ticket_payments (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  ticket_id UUID NOT NULL REFERENCES pos_tickets(id) ON DELETE CASCADE,
  method VARCHAR(20) NOT NULL CHECK (method IN ('cash', 'scanlinkpay')),
  amount_cents BIGINT NOT NULL CHECK (amount_cents > 0),
  -- Espèces : montant remis par le client (pour calculer la monnaie à rendre).
  received_cents BIGINT,
  status VARCHAR(20) NOT NULL DEFAULT 'confirmed' CHECK (status IN ('pending', 'confirmed')),
  payment_request_id UUID REFERENCES payment_requests(id),
  created_by UUID REFERENCES auth.users(id),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_pos_ticket_payments_ticket_id ON pos_ticket_payments(ticket_id);
CREATE INDEX IF NOT EXISTS idx_pos_ticket_payments_payment_request_id ON pos_ticket_payments(payment_request_id);
CREATE INDEX IF NOT EXISTS idx_pos_tickets_merchant_status ON pos_tickets(merchant_id, status);
CREATE INDEX IF NOT EXISTS idx_pos_tickets_session ON pos_tickets(cash_register_session_id);

ALTER TABLE pos_ticket_payments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS pos_ticket_payments_select ON pos_ticket_payments;
CREATE POLICY pos_ticket_payments_select ON pos_ticket_payments FOR SELECT USING (
  EXISTS (SELECT 1 FROM pos_tickets t WHERE t.id = pos_ticket_payments.ticket_id AND public.is_stock_manager(t.merchant_id))
);
DROP POLICY IF EXISTS pos_ticket_payments_insert ON pos_ticket_payments;
CREATE POLICY pos_ticket_payments_insert ON pos_ticket_payments FOR INSERT WITH CHECK (
  EXISTS (SELECT 1 FROM pos_tickets t WHERE t.id = pos_ticket_payments.ticket_id AND public.is_stock_manager(t.merchant_id))
);
DROP POLICY IF EXISTS pos_ticket_payments_update ON pos_ticket_payments;
CREATE POLICY pos_ticket_payments_update ON pos_ticket_payments FOR UPDATE USING (
  EXISTS (SELECT 1 FROM pos_tickets t WHERE t.id = pos_ticket_payments.ticket_id AND public.is_stock_manager(t.merchant_id))
);

-- ============================================================================
-- 035_inventory_counts.sql
-- ============================================================================
-- ============================================================================
-- 035_inventory_counts.sql — Module Supermarché, Phase 3: inventaires
-- physiques (spec 1.4 — inventaires tournants par catégorie ou totaux,
-- saisie des comptages, régularisation avec rapport de démarque).
--
-- Un inventory_count fige au démarrage une ligne par produit en rayon
-- (scope_category NULL = inventaire total) avec le stock THÉORIQUE
-- (expected_qty). Le comptage se saisit ensuite sans interrompre les ventes :
-- à la validation, l'ajustement appliqué est counted − quantité COURANTE
-- (pas counted − expected, sinon une vente passée pendant le comptage serait
-- comptée deux fois), tandis que le rapport d'écarts compare counted −
-- expected pour la démarque.
--
-- Run once in the Supabase SQL editor, same as previous migrations.
-- ============================================================================

CREATE TABLE IF NOT EXISTS inventory_counts (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  merchant_id UUID NOT NULL REFERENCES merchants(id) ON DELETE CASCADE,
  -- NULL = inventaire total ; sinon une des catégories de stock_items
  -- (inventaire tournant par rayon).
  scope_category VARCHAR(100),
  status VARCHAR(20) NOT NULL DEFAULT 'counting' CHECK (status IN ('counting', 'completed', 'cancelled')),
  created_by UUID NOT NULL REFERENCES auth.users(id),
  completed_by UUID REFERENCES auth.users(id),
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  completed_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS inventory_count_lines (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  count_id UUID NOT NULL REFERENCES inventory_counts(id) ON DELETE CASCADE,
  stock_item_id UUID NOT NULL REFERENCES stock_items(id) ON DELETE CASCADE,
  product_name_snapshot VARCHAR(255) NOT NULL,
  category_snapshot VARCHAR(100),
  unit_price_cents_snapshot BIGINT NOT NULL DEFAULT 0,
  currency VARCHAR(10) NOT NULL DEFAULT 'CDF',
  expected_qty INT NOT NULL,
  counted_qty INT,                 -- NULL tant que la ligne n'est pas comptée
  variance INT,                    -- counted − expected, figé à la validation
  counted_at TIMESTAMPTZ,
  UNIQUE (count_id, stock_item_id)
);

CREATE INDEX IF NOT EXISTS idx_inventory_counts_merchant_id ON inventory_counts(merchant_id);
CREATE INDEX IF NOT EXISTS idx_inventory_count_lines_count_id ON inventory_count_lines(count_id);

-- RLS — même garde que le reste du module : is_stock_manager couvre le
-- propriétaire de la boutique, le propriétaire de l'organisation et les
-- employés de l'org (magasinier notamment). Le backend écrit via le
-- service-role en parallèle.
ALTER TABLE inventory_counts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS inventory_counts_select ON inventory_counts;
CREATE POLICY inventory_counts_select ON inventory_counts FOR SELECT USING (public.is_stock_manager(inventory_counts.merchant_id));
DROP POLICY IF EXISTS inventory_counts_insert ON inventory_counts;
CREATE POLICY inventory_counts_insert ON inventory_counts FOR INSERT WITH CHECK (public.is_stock_manager(inventory_counts.merchant_id));
DROP POLICY IF EXISTS inventory_counts_update ON inventory_counts;
CREATE POLICY inventory_counts_update ON inventory_counts FOR UPDATE USING (public.is_stock_manager(inventory_counts.merchant_id));

ALTER TABLE inventory_count_lines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS inventory_count_lines_select ON inventory_count_lines;
CREATE POLICY inventory_count_lines_select ON inventory_count_lines FOR SELECT USING (
  EXISTS (SELECT 1 FROM inventory_counts c WHERE c.id = inventory_count_lines.count_id AND public.is_stock_manager(c.merchant_id))
);
DROP POLICY IF EXISTS inventory_count_lines_insert ON inventory_count_lines;
CREATE POLICY inventory_count_lines_insert ON inventory_count_lines FOR INSERT WITH CHECK (
  EXISTS (SELECT 1 FROM inventory_counts c WHERE c.id = inventory_count_lines.count_id AND public.is_stock_manager(c.merchant_id))
);
DROP POLICY IF EXISTS inventory_count_lines_update ON inventory_count_lines;
CREATE POLICY inventory_count_lines_update ON inventory_count_lines FOR UPDATE USING (
  EXISTS (SELECT 1 FROM inventory_counts c WHERE c.id = inventory_count_lines.count_id AND public.is_stock_manager(c.merchant_id))
);

-- ============================================================================
-- 036_stock_categories_and_password.sql
-- ============================================================================
-- ============================================================================
-- 033_stock_categories_and_password.sql — Categorized stock items with
-- per-category dynamic attributes, a product image, and an organization-wide
-- "stock management password" gate on editing/deleting an item.
--
-- Categories are a fixed 5-value enum (the sector-specific list the user
-- defined for "Shop d'appareils électroniques"), but the specs that go with
-- each one vary wildly (a CPU's socket vs a cable's connector type), so
-- they're NOT individual columns — `attributes` is a free-form JSONB bag the
-- frontend reads/writes per category via a shared config
-- (stock-categories.ts), same reasoning migration 031 gave for keeping
-- sector-specific stuff out of the schema where it could instead be
-- optional/JSONB.
--
-- The stock password is intentionally organization-wide (one shared secret
-- for the whole module, not per-user) — it protects against accidental
-- edits/deletes by anyone with stock access (owner or magasinier), not
-- against a specific user. Mirrors wallet_pin's shape (hash + attempt
-- counter + lockout) in wallet-pin.service.ts, just scoped to
-- organizations instead of profiles.
-- Run once in the Supabase SQL editor, same as previous migrations.
-- ============================================================================

DO $$ BEGIN
  CREATE TYPE stock_item_category AS ENUM (
    'telephonie_mobilite',
    'ordinateurs',
    'composants_informatiques',
    'audio_hifi',
    'accessoires'
  );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

ALTER TABLE stock_items ADD COLUMN IF NOT EXISTS category stock_item_category;
ALTER TABLE stock_items ADD COLUMN IF NOT EXISTS item_type VARCHAR(255);
ALTER TABLE stock_items ADD COLUMN IF NOT EXISTS attributes JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE stock_items ADD COLUMN IF NOT EXISTS image_url TEXT;
ALTER TABLE stock_items ADD COLUMN IF NOT EXISTS description TEXT;

CREATE INDEX IF NOT EXISTS idx_stock_items_category ON stock_items(category);

ALTER TABLE organizations ADD COLUMN IF NOT EXISTS stock_password_hash TEXT;
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS stock_password_attempts INT NOT NULL DEFAULT 0;
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS stock_password_locked_until TIMESTAMPTZ;

insert into storage.buckets (id, name, public, file_size_limit)
values ('product-images', 'product-images', true, 2097152)
on conflict (id) do update set file_size_limit = 2097152;

drop policy if exists "Public read access to product-images" on storage.objects;
create policy "Public read access to product-images"
  on storage.objects for select
  using (bucket_id = 'product-images');

-- ============================================================================
-- 037_sales.sql
-- ============================================================================
-- ============================================================================
-- 034_sales.sql — Ventes de l'entreprise (module Ventes).
--
-- Une vente = un panier d'articles de stock + un paiement. Le paiement passe
-- par le flux wallet existant (payment_requests -> payWithWallet ->
-- transactions), ou est enregistré payé immédiatement en espèces.
--
-- unit_cost_cents est figé au moment de la vente (copié depuis
-- stock_items.cost_price_cents) : les marges passées ne doivent pas bouger
-- si le prix d'achat d'un article change ensuite.
-- Exécuter une fois dans le SQL Editor de Supabase.
-- ============================================================================

CREATE TABLE IF NOT EXISTS sales (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  merchant_id UUID NOT NULL REFERENCES merchants(id) ON DELETE CASCADE,
  reference VARCHAR(100) UNIQUE NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'PAID', 'CANCELLED')),
  payment_method VARCHAR(20) NOT NULL CHECK (payment_method IN ('wallet', 'cash')),
  currency VARCHAR(10) NOT NULL DEFAULT 'CDF',
  total_cents BIGINT NOT NULL CHECK (total_cents >= 0),
  payment_request_id UUID REFERENCES payment_requests(id) ON DELETE SET NULL,
  transaction_id UUID REFERENCES transactions(id) ON DELETE SET NULL,
  created_by UUID REFERENCES auth.users(id),
  paid_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS sale_items (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  sale_id UUID NOT NULL REFERENCES sales(id) ON DELETE CASCADE,
  stock_item_id UUID REFERENCES stock_items(id) ON DELETE SET NULL,
  name VARCHAR(255) NOT NULL,
  category VARCHAR(100),
  quantity INT NOT NULL CHECK (quantity > 0),
  unit_price_cents BIGINT NOT NULL CHECK (unit_price_cents >= 0),
  unit_cost_cents BIGINT NOT NULL DEFAULT 0 CHECK (unit_cost_cents >= 0),
  currency VARCHAR(10) NOT NULL DEFAULT 'CDF',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_sales_organization_id ON sales(organization_id);
CREATE INDEX IF NOT EXISTS idx_sales_paid_at ON sales(paid_at);
CREATE INDEX IF NOT EXISTS idx_sale_items_sale_id ON sale_items(sale_id);
CREATE INDEX IF NOT EXISTS idx_sale_items_stock_item_id ON sale_items(stock_item_id);

DROP TRIGGER IF EXISTS set_updated_at ON sales;
CREATE TRIGGER set_updated_at BEFORE UPDATE ON sales
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE sales ENABLE ROW LEVEL SECURITY;
ALTER TABLE sale_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS sales_select ON sales;
CREATE POLICY sales_select ON sales FOR SELECT USING (public.is_stock_manager(sales.merchant_id));

DROP POLICY IF EXISTS sale_items_select ON sale_items;
CREATE POLICY sale_items_select ON sale_items FOR SELECT USING (
  EXISTS (SELECT 1 FROM sales s WHERE s.id = sale_items.sale_id AND public.is_stock_manager(s.merchant_id))
);

DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE sales;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ============================================================================
-- 038_sales_history_and_invoice.sql
-- ============================================================================
-- 035_sales_history_and_invoice.sql
-- Invoice detail and sales history.
--
-- sale_items.details: snapshot of the product sheet at the time of the sale
-- (brand, model, condition, serial/IMEI, warranty, category attributes such as
-- RAM or storage). Stored once per line so the invoice stays correct even if
-- the stock item is edited or deleted later.
--
-- sales.history_hidden_at: archive flag. Setting it removes the sale from the
-- history list only. The sale row and its lines are never deleted, so the
-- dashboards and the accounting totals are unchanged.

ALTER TABLE sale_items
  ADD COLUMN IF NOT EXISTS details JSONB NOT NULL DEFAULT '{}'::jsonb;

ALTER TABLE sales
  ADD COLUMN IF NOT EXISTS history_hidden_at TIMESTAMPTZ NULL;

CREATE INDEX IF NOT EXISTS idx_sales_history_visible
  ON sales (organization_id, created_at DESC)
  WHERE history_hidden_at IS NULL;

-- ============================================================================
-- 039_platform_settings.sql
-- ============================================================================
-- ============================================================================
-- 039_platform_settings.sql — Platform-wide switches the super admin controls.
--
-- A SINGLE row (id = 1), same shape as expense_tracker_settings (025): these
-- are global decisions for the whole platform, not per-organization ones.
--
-- screenshot_protection: when true, the Android app sets FLAG_SECURE on its
-- window — screenshots, screen recordings and the recent-apps preview come
-- out black, on every account (what WhatsApp does). Browsers offer no such
-- control, so the web/PWA version can't be protected.
--
-- Read publicly through the API (GET /platform/settings is @Public — the
-- login and PIN screens must be protected too); written only by the API with
-- the service key (PUT /admin/platform-settings, super_admin).
-- Run once in the Supabase SQL editor, same as previous migrations.
-- ============================================================================

CREATE TABLE IF NOT EXISTS platform_settings (
  id SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  screenshot_protection BOOLEAN NOT NULL DEFAULT false,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL
);

INSERT INTO platform_settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING;

-- No policies: only the API (service key, bypasses RLS) reads and writes it.
ALTER TABLE platform_settings ENABLE ROW LEVEL SECURITY;

-- ============================================================================
-- 040_settlement_and_refund_integrity.sql
-- ============================================================================
-- ============================================================================
-- 040_settlement_and_refund_integrity.sql — Payout account + race-free
-- settlements and refunds.
--
-- 1. merchants.settlement_account: where the platform sends a merchant's
--    money ({method, operator, number, holder_name, ...}). The API already
--    listed this field as updatable, but the column never existed, so an
--    admin processing a settlement had no way to know where to pay.
--    settlements.payout_account snapshots it at request time, so a later
--    edit never changes where an already-requested payout goes.
--
-- 2. create_merchant_settlements(): the API used to read the unsettled
--    transactions, insert the settlement, then tag the transactions — two
--    concurrent requests (a double tap) could both read the same rows and
--    produce two settlements paying the same money twice. The function locks
--    the merchant row (serializing requests per merchant) and the
--    transaction rows, and only claims rows still unsettled.
--    It also settles PARTIALLY_REFUNDED transactions (net minus what was
--    refunded) and skips any transaction with a refund still in flight.
--
-- 3. reserve_refund(): the "already refunded + this refund <= amount" check
--    was a read-then-insert in the API, so two concurrent refunds could both
--    pass it. The function locks the transaction row, re-checks under the
--    lock, refuses a transaction already included in a settlement (the
--    merchant has been, or is about to be, paid that money), and inserts the
--    refund as PENDING before the PSP is called.
--
-- 4. fail_settlement(): marking a settlement FAILED used to leave its
--    transactions tagged with it forever — the merchant could never request
--    that money again. The function releases them and reverses the ledger
--    entry.
--
-- Only the API (service_role) may call these, like credit_wallet (006).
-- Run once in the Supabase SQL editor, same as previous migrations — BEFORE
-- deploying the API version that calls these functions.
-- ============================================================================

ALTER TABLE merchants ADD COLUMN IF NOT EXISTS settlement_account JSONB;
ALTER TABLE settlements ADD COLUMN IF NOT EXISTS payout_account JSONB;

CREATE INDEX IF NOT EXISTS idx_transactions_merchant_unsettled
  ON transactions(merchant_id) WHERE settlement_id IS NULL;
CREATE INDEX IF NOT EXISTS idx_refunds_transaction_id ON refunds(transaction_id);

-- ----------------------------------------------------------------------------
-- create_merchant_settlements
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_merchant_settlements(
  p_merchant_id UUID,
  p_payout_account JSONB
) RETURNS SETOF settlements
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_currency VARCHAR;
  v_settlement settlements;
  v_period_start TIMESTAMPTZ;
  v_period_end TIMESTAMPTZ := NOW();
BEGIN
  -- Serializes settlement requests for this merchant: a second concurrent
  -- call waits here, then finds every transaction already claimed.
  PERFORM 1 FROM merchants WHERE id = p_merchant_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Merchant % not found', p_merchant_id;
  END IF;

  CREATE TEMP TABLE _settleable ON COMMIT DROP AS
  SELECT t.id,
         COALESCE(t.currency, 'CDF') AS currency,
         t.amount_cents,
         COALESCE(t.psp_fee_cents, 0) AS psp_fee_cents,
         COALESCE(t.platform_fee_cents, 0) AS platform_fee_cents,
         GREATEST(
           COALESCE(t.net_cents, 0) - COALESCE((
             SELECT SUM(r.amount_cents) FROM refunds r
              WHERE r.transaction_id = t.id AND r.status = 'COMPLETED'
           ), 0),
           0
         ) AS net_cents,
         t.created_at
    FROM transactions t
   WHERE t.merchant_id = p_merchant_id
     AND t.status IN ('SUCCESS', 'PARTIALLY_REFUNDED')
     AND t.settlement_id IS NULL
     -- A refund still waiting on the PSP could yet complete: settle that
     -- transaction next time, once its refunded amount is known.
     AND NOT EXISTS (
       SELECT 1 FROM refunds r WHERE r.transaction_id = t.id AND r.status = 'PENDING'
     )
   FOR UPDATE OF t;

  FOR v_currency IN SELECT DISTINCT currency FROM _settleable LOOP
    SELECT MIN(created_at) INTO v_period_start FROM _settleable WHERE currency = v_currency;

    INSERT INTO settlements (
      merchant_id, period_start, period_end, gross_cents, psp_fees_cents,
      platform_fees_cents, net_cents, currency, status, reference,
      transaction_count, payout_account
    )
    SELECT p_merchant_id, v_period_start, v_period_end,
           SUM(amount_cents), SUM(psp_fee_cents), SUM(platform_fee_cents),
           SUM(net_cents), v_currency, 'PENDING',
           'STL-' || to_char(v_period_end, 'YYYYMMDD') || '-' || upper(substr(md5(random()::text), 1, 6)),
           COUNT(*), p_payout_account
      FROM _settleable WHERE currency = v_currency
    RETURNING * INTO v_settlement;

    UPDATE transactions SET settlement_id = v_settlement.id, updated_at = NOW()
     WHERE id IN (SELECT id FROM _settleable WHERE currency = v_currency);

    INSERT INTO ledger_entries (settlement_id, entry_type, direction, amount_cents, currency, reference, source, metadata)
    VALUES (v_settlement.id, 'SETTLEMENT', 'debit', v_settlement.net_cents, v_currency,
            v_settlement.reference, 'system', jsonb_build_object('merchant_id', p_merchant_id));

    RETURN NEXT v_settlement;
  END LOOP;

  RETURN;
END;
$$ LANGUAGE plpgsql;

-- ----------------------------------------------------------------------------
-- fail_settlement
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fail_settlement(
  p_settlement_id UUID,
  p_notes TEXT DEFAULT NULL
) RETURNS settlements
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_settlement settlements;
BEGIN
  UPDATE settlements
     SET status = 'FAILED',
         notes = COALESCE(p_notes, notes),
         updated_at = NOW()
   WHERE id = p_settlement_id AND status IN ('PENDING', 'PROCESSING')
  RETURNING * INTO v_settlement;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Settlement % not found or not in a failable state', p_settlement_id;
  END IF;

  -- Give the money back to the merchant's available balance.
  UPDATE transactions SET settlement_id = NULL, updated_at = NOW()
   WHERE settlement_id = p_settlement_id;

  INSERT INTO ledger_entries (settlement_id, entry_type, direction, amount_cents, currency, reference, source, metadata)
  VALUES (p_settlement_id, 'SETTLEMENT', 'credit', v_settlement.net_cents, v_settlement.currency,
          v_settlement.reference, 'system',
          jsonb_build_object('merchant_id', v_settlement.merchant_id, 'reason', 'settlement_failed'));

  RETURN v_settlement;
END;
$$ LANGUAGE plpgsql;

-- ----------------------------------------------------------------------------
-- reserve_refund
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.reserve_refund(
  p_transaction_id UUID,
  p_amount_cents BIGINT,
  p_reason TEXT,
  p_processed_by UUID
) RETURNS refunds
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tx transactions;
  v_already BIGINT;
  v_refund refunds;
BEGIN
  IF p_amount_cents <= 0 THEN
    RAISE EXCEPTION 'REFUND_INVALID_AMOUNT';
  END IF;

  SELECT * INTO v_tx FROM transactions WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'REFUND_TX_NOT_FOUND';
  END IF;

  IF v_tx.status NOT IN ('SUCCESS', 'PARTIALLY_REFUNDED') THEN
    RAISE EXCEPTION 'REFUND_TX_NOT_REFUNDABLE';
  END IF;

  IF v_tx.settlement_id IS NOT NULL THEN
    RAISE EXCEPTION 'REFUND_TX_SETTLED';
  END IF;

  SELECT COALESCE(SUM(amount_cents), 0) INTO v_already
    FROM refunds
   WHERE transaction_id = p_transaction_id AND status IN ('PENDING', 'COMPLETED');

  IF v_already + p_amount_cents > v_tx.amount_cents THEN
    RAISE EXCEPTION 'REFUND_EXCEEDS_AMOUNT';
  END IF;

  INSERT INTO refunds (transaction_id, amount_cents, currency, reason, status, processed_by)
  VALUES (p_transaction_id, p_amount_cents, v_tx.currency, p_reason, 'PENDING', p_processed_by)
  RETURNING * INTO v_refund;

  RETURN v_refund;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.create_merchant_settlements(UUID, JSONB) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fail_settlement(UUID, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reserve_refund(UUID, BIGINT, TEXT, UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_merchant_settlements(UUID, JSONB) TO service_role;
GRANT EXECUTE ON FUNCTION public.fail_settlement(UUID, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.reserve_refund(UUID, BIGINT, TEXT, UUID) TO service_role;

-- ============================================================================
-- 041_automatic_merchant_payouts.sql
-- ============================================================================
-- ============================================================================
-- 041_automatic_merchant_payouts.sql — Merchants are paid straight into their
-- ScanLinkPay wallet; refunds come out of that wallet.
--
-- Until now a merchant's share of each sale sat in a "settlement balance"
-- that had to be requested by hand and paid out manually by an admin. Now,
-- the moment a payment succeeds:
--   net = amount - PSP fee - platform commission (the rule the super_admin
--   configures) is credited to the wallet of the merchant's OWNER — for an
--   enterprise store that is the owner of the enterprise.
--
-- 1. credit_merchant_wallet(transaction_id): credits that net amount exactly
--    once. Locks the transaction and stamps wallet_credited_at, so a webhook
--    arriving twice, or the retry job below, can never credit it twice.
--
-- 2. refund_to_client_wallet(...): a refund is paid out of the merchant's
--    wallet into the paying client's wallet, in one database transaction.
--    It is refused when the merchant's wallet doesn't hold enough (they
--    refund in cash instead — or top up first), and when the payer has no
--    ScanLinkPay account (CinetPay has no refund API, so there is nowhere to
--    send the money). The balance can therefore never go negative.
--
-- 3. The manual "request a settlement" flow is switched off (execute right
--    revoked below). Existing settlements stay readable for the admin.
--
-- Run once in the Supabase SQL editor, same as previous migrations — BEFORE
-- deploying the API version that calls these functions.
-- ============================================================================

ALTER TABLE transactions ADD COLUMN IF NOT EXISTS wallet_credited_at TIMESTAMPTZ;
ALTER TABLE transactions ADD COLUMN IF NOT EXISTS credited_wallet_id UUID REFERENCES wallets(id);

-- Transactions already included in a settlement were paid out the old way:
-- mark them so the retry job doesn't credit them a second time. Any other
-- existing transaction is still owed to its merchant and gets credited by
-- the retry job.
UPDATE transactions SET wallet_credited_at = NOW() WHERE settlement_id IS NOT NULL AND wallet_credited_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_transactions_wallet_uncredited
  ON transactions(created_at) WHERE wallet_credited_at IS NULL AND status IN ('SUCCESS', 'PARTIALLY_REFUNDED');

-- ----------------------------------------------------------------------------
-- credit_merchant_wallet
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.credit_merchant_wallet(p_transaction_id UUID)
RETURNS BIGINT
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tx transactions;
  v_owner UUID;
  v_wallet UUID;
  v_balance BIGINT;
BEGIN
  SELECT * INTO v_tx FROM transactions WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TX_NOT_FOUND';
  END IF;

  -- Already credited: nothing to do (this is what makes retries safe).
  IF v_tx.wallet_credited_at IS NOT NULL THEN
    RETURN NULL;
  END IF;

  IF v_tx.status NOT IN ('SUCCESS', 'PARTIALLY_REFUNDED') THEN
    RAISE EXCEPTION 'TX_NOT_SUCCESSFUL';
  END IF;

  SELECT owner_id INTO v_owner FROM merchants WHERE id = v_tx.merchant_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'MERCHANT_NOT_FOUND';
  END IF;

  -- One wallet per user; the owner may not have opened theirs yet.
  SELECT id INTO v_wallet FROM wallets WHERE user_id = v_owner;
  IF v_wallet IS NULL THEN
    INSERT INTO wallets (user_id, wallet_number)
    VALUES (v_owner, generate_wallet_number(v_owner))
    ON CONFLICT (user_id) DO NOTHING;
    SELECT id INTO v_wallet FROM wallets WHERE user_id = v_owner;
  END IF;

  IF COALESCE(v_tx.net_cents, 0) > 0 THEN
    v_balance := credit_wallet(
      v_wallet, v_tx.net_cents, 'PAYMENT', 'PAYMENT-' || v_tx.reference, v_tx.currency,
      jsonb_build_object('transaction_id', v_tx.id, 'merchant_id', v_tx.merchant_id)
    );
  END IF;

  UPDATE transactions
     SET wallet_credited_at = NOW(), credited_wallet_id = v_wallet, updated_at = NOW()
   WHERE id = p_transaction_id;

  RETURN v_balance;
END;
$$ LANGUAGE plpgsql;

-- ----------------------------------------------------------------------------
-- refund_to_client_wallet
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.refund_to_client_wallet(
  p_transaction_id UUID,
  p_amount_cents BIGINT,
  p_reason TEXT,
  p_processed_by UUID
) RETURNS refunds
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tx transactions;
  v_owner UUID;
  v_merchant_wallet UUID;
  v_client_wallet UUID;
  v_already BIGINT;
  v_balance BIGINT;
  v_total_refunded BIGINT;
  v_refund refunds;
BEGIN
  IF p_amount_cents <= 0 THEN
    RAISE EXCEPTION 'REFUND_INVALID_AMOUNT';
  END IF;

  SELECT * INTO v_tx FROM transactions WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'REFUND_TX_NOT_FOUND';
  END IF;

  IF v_tx.status NOT IN ('SUCCESS', 'PARTIALLY_REFUNDED') THEN
    RAISE EXCEPTION 'REFUND_TX_NOT_REFUNDABLE';
  END IF;

  -- Paid out the old way (manual settlement): the money already left the
  -- platform for the merchant, so it can't be clawed back from a wallet.
  IF v_tx.settlement_id IS NOT NULL THEN
    RAISE EXCEPTION 'REFUND_TX_SETTLED';
  END IF;

  IF v_tx.client_id IS NULL THEN
    RAISE EXCEPTION 'REFUND_NO_CLIENT_ACCOUNT';
  END IF;

  SELECT COALESCE(SUM(amount_cents), 0) INTO v_already
    FROM refunds WHERE transaction_id = p_transaction_id AND status IN ('PENDING', 'COMPLETED');
  IF v_already + p_amount_cents > v_tx.amount_cents THEN
    RAISE EXCEPTION 'REFUND_EXCEEDS_AMOUNT';
  END IF;

  SELECT owner_id INTO v_owner FROM merchants WHERE id = v_tx.merchant_id;
  SELECT id INTO v_merchant_wallet FROM wallets WHERE user_id = v_owner;
  SELECT id INTO v_client_wallet FROM wallets WHERE user_id = v_tx.client_id;

  IF v_client_wallet IS NULL THEN
    RAISE EXCEPTION 'REFUND_NO_CLIENT_ACCOUNT';
  END IF;
  IF v_merchant_wallet IS NULL THEN
    RAISE EXCEPTION 'REFUND_INSUFFICIENT_BALANCE:0:%', p_amount_cents;
  END IF;

  -- Always lock the two wallets in the same order, or two refunds going in
  -- opposite directions could deadlock each other.
  PERFORM 1 FROM wallets WHERE id IN (v_merchant_wallet, v_client_wallet) ORDER BY id FOR UPDATE;

  SELECT COALESCE(SUM(CASE WHEN direction = 'credit' THEN amount_cents ELSE -amount_cents END), 0)
    INTO v_balance
    FROM ledger_entries WHERE wallet_id = v_merchant_wallet AND currency = v_tx.currency;

  IF v_balance < p_amount_cents THEN
    RAISE EXCEPTION 'REFUND_INSUFFICIENT_BALANCE:%:%', v_balance, p_amount_cents;
  END IF;

  INSERT INTO refunds (transaction_id, amount_cents, currency, reason, status, processed_by)
  VALUES (p_transaction_id, p_amount_cents, v_tx.currency, p_reason, 'COMPLETED', p_processed_by)
  RETURNING * INTO v_refund;

  PERFORM debit_wallet(v_merchant_wallet, p_amount_cents, 'REFUND', 'REFUND-' || v_refund.id, v_tx.currency,
    jsonb_build_object('refund_id', v_refund.id, 'transaction_id', v_tx.id, 'direction', 'refund_given'));
  PERFORM credit_wallet(v_client_wallet, p_amount_cents, 'REFUND', 'REFUND-' || v_refund.id, v_tx.currency,
    jsonb_build_object('refund_id', v_refund.id, 'transaction_id', v_tx.id, 'direction', 'refund_received'));

  INSERT INTO ledger_entries (transaction_id, entry_type, direction, amount_cents, currency, reference, source, metadata)
  VALUES (v_tx.id, 'REFUND', 'debit', p_amount_cents, v_tx.currency, v_tx.reference, 'system',
          jsonb_build_object('refund_id', v_refund.id));

  SELECT COALESCE(SUM(amount_cents), 0) INTO v_total_refunded
    FROM refunds WHERE transaction_id = p_transaction_id AND status = 'COMPLETED';

  UPDATE transactions
     SET status = CASE WHEN v_total_refunded >= v_tx.amount_cents THEN 'REFUNDED' ELSE 'PARTIALLY_REFUNDED' END::transaction_status,
         updated_at = NOW()
   WHERE id = p_transaction_id;

  RETURN v_refund;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.credit_merchant_wallet(UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.refund_to_client_wallet(UUID, BIGINT, TEXT, UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.credit_merchant_wallet(UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.refund_to_client_wallet(UUID, BIGINT, TEXT, UUID) TO service_role;

-- Manual settlement requests are gone: nobody should be able to claim the
-- same money a second time through the old function.
REVOKE EXECUTE ON FUNCTION public.create_merchant_settlements(UUID, JSONB) FROM service_role;

-- ============================================================================
-- 042_withdrawal_payouts.sql
-- ============================================================================
-- ============================================================================
-- 042_withdrawal_payouts.sql — Real withdrawals: state changes that can't be
-- applied twice.
--
-- A withdrawal now goes  PENDING (funds reserved, payout not yet accepted)
--                     -> PROCESSING (the payment provider accepted it)
--                     -> SUCCESS  (the provider confirmed the money was sent)
--                        or REVERSED (it failed: the wallet gets its money back).
--
-- Three things can try to settle the same withdrawal at once: the request
-- itself, the reconciliation job, and (later) the provider's callback. The
-- functions below lock the row, only act on a withdrawal that is still open,
-- and return NULL otherwise — so a withdrawal is refunded at most once and
-- can never be both paid and refunded.
--
-- Only the API (service_role) may call these.
-- Run once in the Supabase SQL editor, BEFORE deploying the API version that
-- calls them.
-- ============================================================================

CREATE INDEX IF NOT EXISTS idx_withdrawals_open
  ON withdrawals(updated_at) WHERE status IN ('PENDING', 'PROCESSING');

-- ----------------------------------------------------------------------------
-- mark_withdrawal_processing: the provider accepted the payout (not final yet).
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.mark_withdrawal_processing(
  p_withdrawal_id UUID,
  p_psp_reference TEXT
) RETURNS withdrawals
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row withdrawals;
BEGIN
  UPDATE withdrawals
     SET status = 'PROCESSING',
         psp_reference = COALESCE(p_psp_reference, psp_reference),
         updated_at = NOW()
   WHERE id = p_withdrawal_id AND status = 'PENDING'
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$ LANGUAGE plpgsql;

-- ----------------------------------------------------------------------------
-- finish_withdrawal: the provider confirmed the money was sent.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.finish_withdrawal(
  p_withdrawal_id UUID,
  p_psp_reference TEXT
) RETURNS withdrawals
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row withdrawals;
BEGIN
  UPDATE withdrawals
     SET status = 'SUCCESS',
         psp_reference = COALESCE(p_psp_reference, psp_reference),
         failure_reason = NULL,
         updated_at = NOW()
   WHERE id = p_withdrawal_id AND status IN ('PENDING', 'PROCESSING')
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$ LANGUAGE plpgsql;

-- ----------------------------------------------------------------------------
-- fail_withdrawal: the money was NOT sent — give the wallet back the amount
-- and the fee, in the same database transaction as the status change.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fail_withdrawal(
  p_withdrawal_id UUID,
  p_reason TEXT
) RETURNS withdrawals
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row withdrawals;
BEGIN
  SELECT * INTO v_row FROM withdrawals WHERE id = p_withdrawal_id FOR UPDATE;
  IF NOT FOUND OR v_row.status NOT IN ('PENDING', 'PROCESSING') THEN
    RETURN NULL;
  END IF;

  PERFORM credit_wallet(
    v_row.wallet_id, v_row.amount_cents + v_row.fee_cents, 'ADJUSTMENT',
    'WITHDRAWAL-REVERSAL-' || v_row.id, v_row.currency,
    jsonb_build_object('withdrawal_id', v_row.id, 'reason', p_reason)
  );

  UPDATE withdrawals
     SET status = 'REVERSED', failure_reason = p_reason, updated_at = NOW()
   WHERE id = p_withdrawal_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.mark_withdrawal_processing(UUID, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.finish_withdrawal(UUID, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fail_withdrawal(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mark_withdrawal_processing(UUID, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.finish_withdrawal(UUID, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.fail_withdrawal(UUID, TEXT) TO service_role;

-- ============================================================================
-- 043_lock_down_functions.sql
-- ============================================================================
-- ============================================================================
-- 043_lock_down_functions.sql — Only the API may run the database functions.
--
-- THE PROBLEM. Supabase hands EXECUTE on every new function in the public
-- schema to the roles `anon` and `authenticated` (via default privileges).
-- Earlier migrations only ran `REVOKE ALL ... FROM PUBLIC`, which does NOT
-- take those role-specific grants away. The `anon` key is public — it ships
-- in the web app — so anyone could call, straight over the REST API,
--   POST /rest/v1/rpc/credit_wallet   {wallet, amount, ...}
-- and add money to any wallet (and debit_wallet, transfer_wallet,
-- finish_withdrawal, ... likewise). Confirmed against a live project: the
-- call ran and only failed because the wallet id it was given didn't exist.
--
-- THE FIX. Every function of the public schema is revoked from PUBLIC, anon
-- and authenticated and granted to service_role only (the key the API uses,
-- never sent to a browser). Left alone:
--   - functions that belong to an extension (pgcrypto, uuid-ossp, ...);
--   - the five small helpers that row-level-security policies call while
--     evaluating a request as the signed-in user (is_admin, is_merchant_user,
--     is_org_owner_of_merchant, is_stock_manager, is_tontine_member): they only
--     answer a yes/no question about the caller and write nothing.
-- The manual-settlement function switched off in 041 stays off for everyone.
--
-- Default privileges are changed too, so functions added by FUTURE migrations
-- are not exposed again. Consequence: a future function that an RLS policy
-- needs must be granted to `authenticated` explicitly.
--
-- Run once in the Supabase SQL editor — as soon as possible.
-- ============================================================================

DO $$
DECLARE
  f RECORD;
BEGIN
  FOR f IN
    SELECT p.oid::regprocedure AS sig, p.proname
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public'
       AND p.prokind = 'f'
       AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = p.oid AND d.deptype = 'e')
       AND p.proname NOT IN (
         'is_admin', 'is_merchant_user', 'is_org_owner_of_merchant', 'is_stock_manager', 'is_tontine_member'
       )
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated', f.sig);
    IF f.proname = 'create_merchant_settlements' THEN
      EXECUTE format('REVOKE ALL ON FUNCTION %s FROM service_role', f.sig);
    ELSE
      EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f.sig);
    END IF;
  END LOOP;
END $$;

ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO service_role;

-- ============================================================================
-- 044_no_direct_table_writes.sql
-- ============================================================================
-- ============================================================================
-- 044_no_direct_table_writes.sql — Only the API writes to the database.
--
-- THE PROBLEM. Every signed-in user holds a real Supabase JWT (the login
-- response hands it to the web app for Realtime) and the anon key is public,
-- so anyone can talk to PostgREST directly and use whatever the row-level-
-- security policies allow. Several policies allow far too much for a
-- direct, unvalidated write:
--   - user_roles    INSERT own row, any role_id   (grant yourself super_admin)
--   - merchants     UPDATE own row                (status, commission_rule_id)
--   - organizations UPDATE / INSERT own row       (status: skip admin approval)
--   - profiles      UPDATE own row                (pin_attempts, pin_locked_until,
--                   transaction_pin_hash, active_session_id, two_factor_*: reset
--                   the PIN lockout, replace the PIN, drop the single-session lock)
--   - pos_ticket_payments / cash_register_sessions / stock_items ... UPDATE by
--     any store staff (a cashier could mark a pending payment as paid)
-- The API enforces rules on every one of these writes (allowed fields, roles,
-- limits); a direct write skips all of it.
--
-- THE FIX. The web app never writes to a table itself — it only reads and
-- subscribes to Realtime — and the API uses the service_role key. So write
-- privileges on every table are simply taken away from anon and authenticated.
-- Reads (still filtered by RLS) and Realtime are untouched. Future tables are
-- covered by the default privileges below.
--
-- Run once in the Supabase SQL editor — as soon as possible.
-- ============================================================================

REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON ALL TABLES IN SCHEMA public FROM anon, authenticated;
REVOKE USAGE, UPDATE ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated;

ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON TABLES FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE USAGE, UPDATE ON SEQUENCES FROM anon, authenticated;

-- ============================================================================
-- 045_hide_secret_columns.sql
-- ============================================================================
-- ============================================================================
-- 045_hide_secret_columns.sql — Secret columns can't be read through the REST
-- API, not even by their owner.
--
-- A user may read their own row of `profiles` (and an enterprise owner their
-- own row of `organizations`) — RLS allows it — and those rows hold
-- credentials: the transaction PIN hash, the 2FA secret, PIN attempt/lock
-- counters, the single-session columns, the stock-management password hash.
-- A bcrypt hash of a 4-digit PIN is guessed offline in seconds, so anyone
-- holding a stolen session could read the hash and recover the PIN. Only the
-- API (service_role) ever needs those columns.
--
-- Column privileges only bite when the table-level SELECT is removed first,
-- so SELECT is revoked from anon/authenticated and granted back column by
-- column, minus the secrets. The web app never queries these tables itself
-- and Realtime isn't subscribed to them. A column added to these tables later
-- is therefore hidden until it is granted explicitly (fail closed).
--
-- Run once in the Supabase SQL editor, after 043 and 044.
-- ============================================================================

DO $$
DECLARE
  spec RECORD;
  readable TEXT;
BEGIN
  FOR spec IN
    SELECT * FROM (VALUES
      ('profiles', ARRAY['transaction_pin_hash', 'pin_attempts', 'pin_locked_until', 'two_factor_secret', 'active_session_id', 'active_device_id']),
      ('organizations', ARRAY['stock_password_hash', 'stock_password_attempts', 'stock_password_locked_until'])
    ) AS t(tbl, secrets)
  LOOP
    SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position)
      INTO readable
      FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name = spec.tbl AND NOT (column_name = ANY (spec.secrets));

    EXECUTE format('REVOKE SELECT ON public.%I FROM anon, authenticated', spec.tbl);
    EXECUTE format('GRANT SELECT (%s) ON public.%I TO authenticated', readable, spec.tbl);
  END LOOP;
END $$;

-- ============================================================================
-- 046_tontine_contribution_claim.sql
-- ============================================================================
-- ============================================================================
-- 046_tontine_contribution_claim.sql — A tontine contribution is paid once.
--
-- contribute() (the member, with their PIN) and the 9am auto-payment job both
-- checked "is it paid yet?" and then moved the money, so two overlapping
-- attempts — the job running while the member taps "Cotiser", or a double
-- tap with two different idempotency keys — each passed the check and each
-- transferred the full amount to the recipient.
--
-- claimed_at is the lock: a payment attempt first claims the contribution with
-- one atomic UPDATE (only one wins). A claim older than a couple of minutes
-- counts as abandoned (the process died mid-payment) and can be taken again,
-- so a crash never leaves a contribution stuck.
--
-- Run once in the Supabase SQL editor, before deploying the API version that
-- uses it.
-- ============================================================================

ALTER TABLE tontine_contributions ADD COLUMN IF NOT EXISTS claimed_at TIMESTAMPTZ;

-- ============================================================================
-- POS: a ticket can't be paid beyond its total, even by two taps at once.
--
-- The till computed "remaining = total - payments", checked the amount against
-- it, then inserted the payment — three steps with nothing holding the ticket
-- in between. A double tap on "Encaisser" recorded the same cash payment
-- twice: the ticket showed overpaid and the register's expected cash was
-- inflated, which then shows up as a shortage in the cashier's reconciliation.
--
-- add_pos_payment() locks the ticket row, recomputes what is still owed from
-- the payments actually stored, and only then inserts — one statement at a time
-- per ticket. Only the API may call it.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.add_pos_payment(
  p_ticket_id UUID,
  p_method TEXT,
  p_amount_cents BIGINT,
  p_received_cents BIGINT,
  p_status TEXT,
  p_payment_request_id UUID,
  p_created_by UUID
) RETURNS pos_ticket_payments
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_ticket pos_tickets;
  v_paid BIGINT;
  v_payment pos_ticket_payments;
BEGIN
  SELECT * INTO v_ticket FROM pos_tickets WHERE id = p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'POS_TICKET_NOT_FOUND';
  END IF;
  IF v_ticket.status <> 'open' THEN
    RAISE EXCEPTION 'POS_TICKET_NOT_OPEN';
  END IF;

  SELECT COALESCE(SUM(amount_cents), 0) INTO v_paid FROM pos_ticket_payments WHERE ticket_id = p_ticket_id;

  IF p_amount_cents <= 0 OR p_amount_cents > v_ticket.total_cents - v_paid THEN
    RAISE EXCEPTION 'POS_PAYMENT_EXCEEDS_REMAINING:%', GREATEST(v_ticket.total_cents - v_paid, 0);
  END IF;

  INSERT INTO pos_ticket_payments (ticket_id, method, amount_cents, received_cents, status, payment_request_id, created_by)
  VALUES (p_ticket_id, p_method, p_amount_cents, p_received_cents, p_status, p_payment_request_id, p_created_by)
  RETURNING * INTO v_payment;

  RETURN v_payment;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.add_pos_payment(UUID, TEXT, BIGINT, BIGINT, TEXT, UUID, UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.add_pos_payment(UUID, TEXT, BIGINT, BIGINT, TEXT, UUID, UUID) TO service_role;

-- ============================================================================
-- Stock can't go below zero, even with two sales at once.
--
-- createMovement() read the quantity, checked "enough left?", then inserted the
-- movement (a trigger applies it to stock_items.quantity): two simultaneous
-- sales of the last unit both passed the check and the stock went to -1.
-- With the constraint the second movement is rejected by the database itself.
-- NOT VALID: it applies to every new/updated row without failing on rows that
-- may already be negative; fix those, then VALIDATE CONSTRAINT.
-- ============================================================================
ALTER TABLE stock_items DROP CONSTRAINT IF EXISTS stock_items_quantity_nonnegative;
ALTER TABLE stock_items ADD CONSTRAINT stock_items_quantity_nonnegative CHECK (quantity >= 0) NOT VALID;

-- ============================================================================
-- 047_savings_hardening.sql
-- ============================================================================
-- ============================================================================
-- 047_savings_hardening.sql — Savings: wallet/user pairing and cheap balances.
--
-- 1. round_up_to_savings, withdraw_from_savings_pot and pay_expense_pro_via_wallet
--    take BOTH a wallet id and a user id and trusted the caller that they
--    match. The API always passes the caller's own wallet, but a function that
--    moves money should not depend on that: with a mismatched pair,
--    round_up_to_savings would debit ANY wallet into someone's pot, and
--    withdraw_from_savings_pot would pay a pot out to ANY wallet. Each now
--    refuses a wallet that doesn't belong to the user. (Before migration 043
--    those functions were also open to the public anon key, which made this
--    exploitable from outside; 043 closed that, this closes the logic.)
--
-- 2. savings_pot_balances(): the savings screen computed each pot's balance by
--    downloading EVERY entry ever recorded (one per round-up, so one per
--    payment) and summing them in the API. It is now a SUM in the database,
--    and the screen only fetches the 20 latest entries it displays.
--
-- Run once in the Supabase SQL editor, after 043. CREATE OR REPLACE keeps the
-- existing grants (service_role only).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.round_up_to_savings(
  p_wallet_id UUID,
  p_user_id UUID,
  p_currency VARCHAR,
  p_amount_cents BIGINT,
  p_reference VARCHAR
) RETURNS BIGINT
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pot_id UUID;
  v_balance BIGINT;
BEGIN
  PERFORM 1 FROM wallets WHERE id = p_wallet_id AND user_id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'WALLET_USER_MISMATCH';
  END IF;

  SELECT id INTO v_pot_id FROM savings_pots WHERE user_id = p_user_id AND currency = p_currency AND round_up_enabled = TRUE;
  IF v_pot_id IS NULL THEN
    RAISE EXCEPTION 'No active % savings pot for user %', p_currency, p_user_id;
  END IF;

  PERFORM public.debit_wallet(p_wallet_id, p_amount_cents, 'ADJUSTMENT'::ledger_entry_type, p_reference, p_currency, jsonb_build_object('pot_id', v_pot_id, 'type', 'roundup_out'));

  INSERT INTO savings_pot_entries (pot_id, type, amount_cents, related_reference)
  VALUES (v_pot_id, 'round_up', p_amount_cents, p_reference);

  SELECT COALESCE(SUM(CASE WHEN type = 'round_up' THEN amount_cents ELSE -amount_cents END), 0)
    INTO v_balance
    FROM savings_pot_entries WHERE pot_id = v_pot_id;

  RETURN v_balance;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.withdraw_from_savings_pot(
  p_wallet_id UUID,
  p_user_id UUID,
  p_currency VARCHAR,
  p_amount_cents BIGINT
) RETURNS BIGINT
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pot_id UUID;
  v_balance BIGINT;
BEGIN
  IF p_amount_cents <= 0 THEN
    RAISE EXCEPTION 'amount_cents must be positive';
  END IF;

  PERFORM 1 FROM wallets WHERE id = p_wallet_id AND user_id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'WALLET_USER_MISMATCH';
  END IF;

  SELECT id INTO v_pot_id FROM savings_pots WHERE user_id = p_user_id AND currency = p_currency FOR UPDATE;
  IF v_pot_id IS NULL THEN
    RAISE EXCEPTION 'No % savings pot for user %', p_currency, p_user_id;
  END IF;

  SELECT COALESCE(SUM(CASE WHEN type = 'round_up' THEN amount_cents ELSE -amount_cents END), 0)
    INTO v_balance
    FROM savings_pot_entries WHERE pot_id = v_pot_id;

  IF v_balance < p_amount_cents THEN
    RAISE EXCEPTION 'Insufficient pot balance: has %, needs %', v_balance, p_amount_cents;
  END IF;

  INSERT INTO savings_pot_entries (pot_id, type, amount_cents) VALUES (v_pot_id, 'withdrawal', p_amount_cents);

  PERFORM public.credit_wallet(p_wallet_id, p_amount_cents, 'ADJUSTMENT'::ledger_entry_type, 'savings-withdrawal', p_currency, jsonb_build_object('pot_id', v_pot_id, 'type', 'roundup_in'));

  RETURN v_balance - p_amount_cents;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.pay_expense_pro_via_wallet(
  p_user_id UUID,
  p_wallet_id UUID,
  p_amount_cents BIGINT,
  p_currency VARCHAR,
  p_reference VARCHAR
) RETURNS TIMESTAMPTZ
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_new_expiry TIMESTAMPTZ;
BEGIN
  PERFORM 1 FROM wallets WHERE id = p_wallet_id AND user_id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'WALLET_USER_MISMATCH';
  END IF;

  PERFORM public.debit_wallet(p_wallet_id, p_amount_cents, 'PLATFORM_FEE'::ledger_entry_type, p_reference, p_currency, jsonb_build_object('kind', 'expense_pro_subscription'));

  INSERT INTO expense_pro_status (user_id, trial_started_at, trial_ends_at, pro_expires_at)
  VALUES (p_user_id, NOW(), NOW(), NOW() + INTERVAL '30 days')
  ON CONFLICT (user_id) DO UPDATE
    SET pro_expires_at = GREATEST(NOW(), COALESCE(expense_pro_status.pro_expires_at, NOW())) + INTERVAL '30 days',
        updated_at = NOW()
  RETURNING pro_expires_at INTO v_new_expiry;

  RETURN v_new_expiry;
END;
$$ LANGUAGE plpgsql;

-- ----------------------------------------------------------------------------
-- savings_pot_balances: one SUM per pot, in the database.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.savings_pot_balances(p_user_id UUID)
RETURNS TABLE (currency VARCHAR, balance_cents BIGINT)
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT p.currency::VARCHAR,
         COALESCE(SUM(CASE WHEN e.type = 'round_up' THEN e.amount_cents ELSE -e.amount_cents END), 0)::BIGINT
    FROM savings_pots p
    LEFT JOIN savings_pot_entries e ON e.pot_id = p.id
   WHERE p.user_id = p_user_id
   GROUP BY p.currency;
$$ LANGUAGE sql STABLE;

REVOKE ALL ON FUNCTION public.savings_pot_balances(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.savings_pot_balances(UUID) TO service_role;

-- ============================================================================
-- 048_admin_security.sql
-- ============================================================================
-- ============================================================================
-- 048_admin_security.sql — Two-factor login for administrators + integrity
-- monitoring.
--
-- 1. profiles gets the bookkeeping the authenticator-app (TOTP) login needs:
--    the last accepted time step (a code can only be used once), hashed
--    one-time recovery codes, and when 2FA was set up. profiles.two_factor_secret
--    and two_factor_enabled already exist (001); the secret is stored
--    ENCRYPTED by the API. Like the other secret columns these are never
--    readable through the public REST API.
--
-- 2. claim_totp_step / consume_recovery_code: single atomic statements, so
--    two simultaneous requests can't both spend the same code.
--
-- 3. negative_wallet_balances(): any wallet whose ledger sums below zero means
--    money was created or a bug let a wallet overdraw. The API checks it every
--    10 minutes and alerts the super admins.
--
-- Run once in the Supabase SQL editor (after 047).
-- ============================================================================

ALTER TABLE profiles ADD COLUMN IF NOT EXISTS two_factor_last_step BIGINT;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS two_factor_recovery_hashes TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS two_factor_enrolled_at TIMESTAMPTZ;

-- Same technique as 045: table-level SELECT is withdrawn and every column
-- EXCEPT the secrets is granted back, so the new columns stay unreadable.
DO $$
DECLARE
  readable TEXT;
BEGIN
  SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position)
    INTO readable
    FROM information_schema.columns
   WHERE table_schema = 'public' AND table_name = 'profiles'
     AND column_name NOT IN (
       'transaction_pin_hash', 'pin_attempts', 'pin_locked_until', 'two_factor_secret',
       'active_session_id', 'active_device_id', 'two_factor_last_step', 'two_factor_recovery_hashes'
     );
  REVOKE SELECT ON public.profiles FROM anon, authenticated;
  EXECUTE format('GRANT SELECT (%s) ON public.profiles TO authenticated', readable);
END $$;

CREATE OR REPLACE FUNCTION public.claim_totp_step(p_user_id UUID, p_step BIGINT)
RETURNS BOOLEAN
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rows INT;
BEGIN
  UPDATE profiles
     SET two_factor_last_step = p_step
   WHERE id = p_user_id
     AND (two_factor_last_step IS NULL OR two_factor_last_step < p_step);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.consume_recovery_code(p_user_id UUID, p_hash TEXT)
RETURNS BOOLEAN
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rows INT;
BEGIN
  UPDATE profiles
     SET two_factor_recovery_hashes = array_remove(two_factor_recovery_hashes, p_hash)
   WHERE id = p_user_id AND p_hash = ANY(two_factor_recovery_hashes);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.negative_wallet_balances()
RETURNS TABLE (wallet_id UUID, currency VARCHAR, balance_cents BIGINT)
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT l.wallet_id, l.currency,
         SUM(CASE WHEN l.direction = 'credit' THEN l.amount_cents ELSE -l.amount_cents END)::BIGINT AS balance_cents
    FROM ledger_entries l
   WHERE l.wallet_id IS NOT NULL
   GROUP BY l.wallet_id, l.currency
  HAVING SUM(CASE WHEN l.direction = 'credit' THEN l.amount_cents ELSE -l.amount_cents END) < 0
$$ LANGUAGE sql STABLE;

REVOKE ALL ON FUNCTION public.claim_totp_step(UUID, BIGINT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.consume_recovery_code(UUID, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.negative_wallet_balances() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_totp_step(UUID, BIGINT) TO service_role;
GRANT EXECUTE ON FUNCTION public.consume_recovery_code(UUID, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.negative_wallet_balances() TO service_role;

-- ============================================================================
-- 049_shared_login_attempts.sql
-- ============================================================================
-- ============================================================================
-- 049_shared_login_attempts.sql — Login / 2FA lockout counters shared by every
-- API instance.
--
-- Until now the failed-attempt counters lived in each API process's memory: two
-- instances gave an attacker two budgets, and a restart wiped the count.
-- record_auth_failure() keeps them in the database instead, atomically (the row
-- is locked while it is updated, so concurrent guesses can't slip past the
-- limit). The API falls back to its in-memory counters if this table or
-- function is unavailable, so applying this migration is not a prerequisite
-- for deploying.
--
-- `key` is a SHA-256 of the account (email or user id), never the email itself.
-- Only the API (service_role) can touch it.
-- Run once in the Supabase SQL editor (after 048).
-- ============================================================================

CREATE TABLE IF NOT EXISTS auth_attempts (
  key TEXT PRIMARY KEY,
  failures INT NOT NULL DEFAULT 0,
  window_started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  locked_until TIMESTAMPTZ
);

ALTER TABLE auth_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON auth_attempts FROM PUBLIC, anon, authenticated;
GRANT ALL ON auth_attempts TO service_role;

-- Records one failure. Returns when the account is locked until (NULL = not
-- locked) and whether THIS failure is the one that triggered the lock.
CREATE OR REPLACE FUNCTION public.record_auth_failure(
  p_key TEXT,
  p_max INT,
  p_window_seconds INT,
  p_lock_seconds INT
) RETURNS TABLE (locked_until TIMESTAMPTZ, just_locked BOOLEAN)
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_now TIMESTAMPTZ := clock_timestamp();
  v_row auth_attempts;
BEGIN
  INSERT INTO auth_attempts (key, failures, window_started_at) VALUES (p_key, 0, v_now)
  ON CONFLICT (key) DO NOTHING;

  SELECT * INTO v_row FROM auth_attempts WHERE key = p_key FOR UPDATE;

  IF v_row.locked_until IS NOT NULL AND v_row.locked_until > v_now THEN
    RETURN QUERY SELECT v_row.locked_until, FALSE;
    RETURN;
  END IF;

  IF v_row.window_started_at < v_now - make_interval(secs => p_window_seconds) THEN
    v_row.failures := 0;
    v_row.window_started_at := v_now;
  END IF;

  v_row.failures := v_row.failures + 1;

  IF v_row.failures >= p_max THEN
    UPDATE auth_attempts
       SET failures = 0, window_started_at = v_now, locked_until = v_now + make_interval(secs => p_lock_seconds)
     WHERE key = p_key
    RETURNING auth_attempts.locked_until INTO v_row.locked_until;
    RETURN QUERY SELECT v_row.locked_until, TRUE;
  ELSE
    UPDATE auth_attempts SET failures = v_row.failures, window_started_at = v_row.window_started_at WHERE key = p_key;
    RETURN QUERY SELECT NULL::TIMESTAMPTZ, FALSE;
  END IF;
END;
$$ LANGUAGE plpgsql;

-- Is the account locked right now? Returns the unlock time, or NULL.
CREATE OR REPLACE FUNCTION public.get_auth_lock(p_key TEXT)
RETURNS TIMESTAMPTZ
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT locked_until FROM auth_attempts WHERE key = p_key AND locked_until > clock_timestamp()
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION public.clear_auth_attempts(p_key TEXT)
RETURNS VOID
SECURITY DEFINER
SET search_path = public
AS $$
  DELETE FROM auth_attempts WHERE key = p_key
$$ LANGUAGE sql;

REVOKE ALL ON FUNCTION public.record_auth_failure(TEXT, INT, INT, INT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.get_auth_lock(TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.clear_auth_attempts(TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_auth_failure(TEXT, INT, INT, INT) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_auth_lock(TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.clear_auth_attempts(TEXT) TO service_role;

-- Housekeeping helper the API calls now and then: forget old, unlocked rows.
CREATE OR REPLACE FUNCTION public.purge_auth_attempts()
RETURNS VOID
SECURITY DEFINER
SET search_path = public
AS $$
  DELETE FROM auth_attempts
   WHERE (locked_until IS NULL OR locked_until < NOW()) AND window_started_at < NOW() - INTERVAL '1 day'
$$ LANGUAGE sql;
REVOKE ALL ON FUNCTION public.purge_auth_attempts() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.purge_auth_attempts() TO service_role;

-- ============================================================================
-- 050_app_access_code.sql
-- ============================================================================
-- ============================================================================
-- 050_app_access_code.sql — The "code d'accès" asked every time the app is
-- opened, left, or idle.
--
-- Each user chooses a 6-digit access code (separate from the account password
-- and from the transaction PIN). The app locks itself on every launch, when it
-- has been in the background, and after a few idle minutes; the code is checked
-- by the API, never by the phone.
--
-- Brute force protection lives here, in the database, because a thief with the
-- unlocked phone can fire many guesses at once:
--   begin_app_code_attempt  — runs BEFORE the code is compared. It refuses while
--                             locked, refuses (and locks) once 5 guesses are
--                             outstanding, otherwise counts the guess. Parallel
--                             requests can therefore never get more than 5
--                             comparisons per lock window.
--   fail_app_code_attempt   — after a wrong code: locks 15 min at the 5th miss;
--                             the 2nd lock in a row returns 'terminate' (the API
--                             then ends the session: full password login needed).
--   clear_app_code_failures — after a right code.
-- The hash itself is never readable through the public REST API (same technique
-- as 045/048). Only the API (service_role) can call the functions.
-- Run once in the Supabase SQL editor (after 049).
-- ============================================================================

ALTER TABLE profiles ADD COLUMN IF NOT EXISTS app_code_hash TEXT;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS app_code_set_at TIMESTAMPTZ;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS app_code_attempts INT NOT NULL DEFAULT 0;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS app_code_lockouts INT NOT NULL DEFAULT 0;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS app_code_locked_until TIMESTAMPTZ;

DO $$
DECLARE
  readable TEXT;
BEGIN
  SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position)
    INTO readable
    FROM information_schema.columns
   WHERE table_schema = 'public' AND table_name = 'profiles'
     AND column_name NOT IN (
       'transaction_pin_hash', 'pin_attempts', 'pin_locked_until', 'two_factor_secret',
       'active_session_id', 'active_device_id', 'two_factor_last_step', 'two_factor_recovery_hashes',
       'app_code_hash', 'app_code_attempts', 'app_code_lockouts', 'app_code_locked_until'
     );
  REVOKE SELECT ON public.profiles FROM anon, authenticated;
  EXECUTE format('GRANT SELECT (%s) ON public.profiles TO authenticated', readable);
END $$;

CREATE OR REPLACE FUNCTION public.begin_app_code_attempt(p_user_id UUID)
RETURNS TABLE (status TEXT, attempts INT, locked_until TIMESTAMPTZ)
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_now TIMESTAMPTZ := clock_timestamp();
  v_row profiles;
BEGIN
  SELECT * INTO v_row FROM profiles WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'missing'::TEXT, 0, NULL::TIMESTAMPTZ;
    RETURN;
  END IF;

  IF v_row.app_code_locked_until IS NOT NULL AND v_row.app_code_locked_until > v_now THEN
    RETURN QUERY SELECT 'locked'::TEXT, v_row.app_code_attempts, v_row.app_code_locked_until;
    RETURN;
  END IF;

  -- Five guesses already spent and none confirmed right: lock now.
  IF v_row.app_code_attempts >= 5 THEN
    UPDATE profiles
       SET app_code_attempts = 0, app_code_lockouts = app_code_lockouts + 1,
           app_code_locked_until = v_now + INTERVAL '15 minutes'
     WHERE id = p_user_id
    RETURNING app_code_lockouts, app_code_locked_until INTO v_row.app_code_lockouts, v_row.app_code_locked_until;
    RETURN QUERY SELECT CASE WHEN v_row.app_code_lockouts >= 2 THEN 'terminate' ELSE 'locked' END::TEXT, 0, v_row.app_code_locked_until;
    RETURN;
  END IF;

  UPDATE profiles SET app_code_attempts = app_code_attempts + 1 WHERE id = p_user_id
  RETURNING app_code_attempts INTO v_row.app_code_attempts;
  RETURN QUERY SELECT 'ok'::TEXT, v_row.app_code_attempts, NULL::TIMESTAMPTZ;
END;
$$ LANGUAGE plpgsql;

-- Called after a wrong code. At the 5th miss the account locks right away.
CREATE OR REPLACE FUNCTION public.fail_app_code_attempt(p_user_id UUID)
RETURNS TABLE (status TEXT, attempts INT, locked_until TIMESTAMPTZ)
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row profiles;
BEGIN
  SELECT * INTO v_row FROM profiles WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'missing'::TEXT, 0, NULL::TIMESTAMPTZ;
    RETURN;
  END IF;

  IF v_row.app_code_attempts >= 5 THEN
    UPDATE profiles
       SET app_code_attempts = 0, app_code_lockouts = app_code_lockouts + 1,
           app_code_locked_until = clock_timestamp() + INTERVAL '15 minutes'
     WHERE id = p_user_id
    RETURNING app_code_lockouts, app_code_locked_until INTO v_row.app_code_lockouts, v_row.app_code_locked_until;
    RETURN QUERY SELECT CASE WHEN v_row.app_code_lockouts >= 2 THEN 'terminate' ELSE 'locked' END::TEXT, 0, v_row.app_code_locked_until;
    RETURN;
  END IF;

  RETURN QUERY SELECT 'ok'::TEXT, v_row.app_code_attempts, NULL::TIMESTAMPTZ;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.clear_app_code_failures(p_user_id UUID)
RETURNS VOID
SECURITY DEFINER
SET search_path = public
AS $$
  UPDATE profiles SET app_code_attempts = 0, app_code_lockouts = 0, app_code_locked_until = NULL WHERE id = p_user_id
$$ LANGUAGE sql;

REVOKE ALL ON FUNCTION public.begin_app_code_attempt(UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.fail_app_code_attempt(UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.clear_app_code_failures(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.begin_app_code_attempt(UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.fail_app_code_attempt(UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.clear_app_code_failures(UUID) TO service_role;

-- ============================================================================
-- 051_staff_deactivation.sql
-- ============================================================================
-- ============================================================================
-- 051_staff_deactivation.sql — Remove an employee's access without deleting
-- their history.
--
-- A departing employee's account is blocked in Supabase Auth (cannot log in)
-- and its sessions are cut by the API; this just records when and by whom, so
-- the Staff screen can show "Accès retiré" and offer to restore it. The sales,
-- stock movements and audit entries they made keep pointing at their account.
-- The API blocks the account FIRST, so access is cut even if this migration has
-- not been applied yet.
-- Run once in the Supabase SQL editor (after 050).
-- ============================================================================

ALTER TABLE organization_staff ADD COLUMN IF NOT EXISTS deactivated_at TIMESTAMPTZ;
ALTER TABLE organization_staff ADD COLUMN IF NOT EXISTS deactivated_by UUID REFERENCES auth.users(id);

-- ============================================================================
-- 052_subscriptions.sql
-- ============================================================================
-- ============================================================================
-- 052_subscriptions.sql — Monthly subscription: one price, everything included.
--
-- A business (organization) subscribes by the month and gets ALL the business
-- tools (till, sales, stock, inventory, statistics, journal, staff). The super
-- admin decides from the admin screen:
--   * the price of ONE month, per currency (CDF / USD);
--   * how long a new business can try everything for free (trial_days);
--   * what happens when the trial ends / a subscription expires: 'read_only'
--     (screens open for reading, nothing can be changed) or 'blocked';
--   * how many days before expiry the patron is warned (reminder_days).
--
-- The owner pays N months from their ScanLinkPay wallet. Paying while the
-- subscription still runs ADDS the months after its current end; paying after
-- it expired restarts from now (access resumes at once). purchase_subscription()
-- does the debit, the record and the extension in one transaction, and is
-- idempotent on its reference.
--
-- All of these tables are for the API only (no direct access from the public key).
-- Run once in the Supabase SQL editor (after 051). It also removes the per-feature
-- "licence" tables of an earlier draft of this migration, if they were created.
-- ============================================================================

ALTER TYPE ledger_entry_type ADD VALUE IF NOT EXISTS 'SUBSCRIPTION';
COMMIT; -- the new enum value must be committed before it is used

-- Earlier per-feature draft (never used in production): drop it.
DROP FUNCTION IF EXISTS public.purchase_license(UUID, UUID, UUID, TEXT[], INT, VARCHAR, BIGINT, BOOLEAN, TEXT);
DROP FUNCTION IF EXISTS public.license_revenue();
DROP TABLE IF EXISTS license_purchases, organization_license_state, organization_licenses,
  license_bundle_prices, license_feature_prices, license_features, license_settings CASCADE;

CREATE TABLE IF NOT EXISTS subscription_prices (
  currency VARCHAR(10) PRIMARY KEY,
  price_month_cents BIGINT NOT NULL CHECK (price_month_cents > 0)
);

CREATE TABLE IF NOT EXISTS subscription_settings (
  id INT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  trial_days INT NOT NULL DEFAULT 30 CHECK (trial_days BETWEEN 0 AND 365),
  trial_end_mode TEXT NOT NULL DEFAULT 'read_only' CHECK (trial_end_mode IN ('read_only', 'blocked')),
  expiry_mode TEXT NOT NULL DEFAULT 'read_only' CHECK (expiry_mode IN ('read_only', 'blocked')),
  reminder_days INT[] NOT NULL DEFAULT '{7,3,1}',
  -- No business's free trial starts before this date: the day this migration is applied, so that
  -- businesses that already exist get a full trial instead of being cut off the day billing ships.
  billing_starts_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_by UUID REFERENCES auth.users(id)
);
ALTER TABLE subscription_settings ADD COLUMN IF NOT EXISTS billing_starts_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
INSERT INTO subscription_settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING;

CREATE TABLE IF NOT EXISTS organization_subscriptions (
  organization_id UUID PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,
  -- NULL until the first payment (the row may exist earlier, to remember trial reminders).
  expires_at TIMESTAMPTZ,
  -- Smallest reminder threshold already sent for the current period (0 = "expired" notice sent).
  last_reminder_days INT,
  trial_last_reminder_days INT,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_organization_subscriptions_expiry ON organization_subscriptions(expires_at);

CREATE TABLE IF NOT EXISTS subscription_purchases (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES organizations(id),
  purchased_by UUID NOT NULL REFERENCES auth.users(id),
  months INT NOT NULL CHECK (months > 0),
  currency VARCHAR(10) NOT NULL,
  amount_cents BIGINT NOT NULL CHECK (amount_cents > 0),
  reference TEXT NOT NULL UNIQUE,
  starts_at TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_subscription_purchases_org ON subscription_purchases(organization_id, created_at DESC);

DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['subscription_prices', 'subscription_settings', 'organization_subscriptions', 'subscription_purchases']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('REVOKE ALL ON %I FROM PUBLIC, anon, authenticated', t);
    EXECUTE format('GRANT ALL ON %I TO service_role', t);
  END LOOP;
END $$;

-- ----------------------------------------------------------------------------
-- purchase_subscription: debit the owner's wallet, record the payment, extend the subscription.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.purchase_subscription(
  p_org UUID,
  p_user UUID,
  p_wallet UUID,
  p_months INT,
  p_currency VARCHAR,
  p_amount BIGINT,
  p_reference TEXT
) RETURNS TABLE (expires_at TIMESTAMPTZ)
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_existing subscription_purchases;
  v_start TIMESTAMPTZ;
  v_end TIMESTAMPTZ;
BEGIN
  IF p_months < 1 OR p_months > 24 THEN RAISE EXCEPTION 'SUBSCRIPTION_INVALID_MONTHS'; END IF;
  IF p_amount <= 0 THEN RAISE EXCEPTION 'SUBSCRIPTION_INVALID_AMOUNT'; END IF;

  -- Only the owner of the business, paying from their own wallet.
  PERFORM 1 FROM organizations WHERE id = p_org AND owner_id = p_user;
  IF NOT FOUND THEN RAISE EXCEPTION 'SUBSCRIPTION_NOT_OWNER'; END IF;
  PERFORM 1 FROM wallets WHERE id = p_wallet AND user_id = p_user;
  IF NOT FOUND THEN RAISE EXCEPTION 'WALLET_USER_MISMATCH'; END IF;

  -- Serialise the payments of one business (so months stack instead of overlapping), and make a
  -- same-reference retry wait for the first request instead of racing it.
  INSERT INTO organization_subscriptions (organization_id) VALUES (p_org) ON CONFLICT (organization_id) DO NOTHING;
  SELECT GREATEST(COALESCE(s.expires_at, NOW()), NOW()) INTO v_start
    FROM organization_subscriptions s WHERE s.organization_id = p_org FOR UPDATE;

  -- Same request twice (double tap, retry): nothing is charged again, the first result is returned.
  SELECT * INTO v_existing FROM subscription_purchases WHERE reference = p_reference;
  IF FOUND THEN
    IF v_existing.organization_id <> p_org THEN RAISE EXCEPTION 'SUBSCRIPTION_REFERENCE_CONFLICT'; END IF;
    RETURN QUERY SELECT v_existing.expires_at;
    RETURN;
  END IF;
  v_end := v_start + make_interval(months => p_months);

  -- Raises 'Insufficient balance' when the wallet doesn't hold enough.
  PERFORM debit_wallet(p_wallet, p_amount, 'SUBSCRIPTION', 'SUBSCRIPTION-' || p_reference, p_currency,
    jsonb_build_object('organization_id', p_org, 'months', p_months));

  INSERT INTO subscription_purchases (organization_id, purchased_by, months, currency, amount_cents, reference, starts_at, expires_at)
  VALUES (p_org, p_user, p_months, p_currency, p_amount, p_reference, v_start, v_end);

  UPDATE organization_subscriptions s
     SET expires_at = v_end, last_reminder_days = NULL, updated_at = NOW()
   WHERE s.organization_id = p_org;

  RETURN QUERY SELECT v_end;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.purchase_subscription(UUID, UUID, UUID, INT, VARCHAR, BIGINT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.purchase_subscription(UUID, UUID, UUID, INT, VARCHAR, BIGINT, TEXT) TO service_role;

-- What the platform earned from subscriptions, per currency (for the super admin screen).
CREATE OR REPLACE FUNCTION public.subscription_revenue()
RETURNS TABLE (currency VARCHAR, total_cents BIGINT, purchases BIGINT)
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT currency, SUM(amount_cents)::BIGINT, COUNT(*)::BIGINT FROM subscription_purchases GROUP BY currency
$$ LANGUAGE sql STABLE;

REVOKE ALL ON FUNCTION public.subscription_revenue() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.subscription_revenue() TO service_role;

-- ============================================================================
-- 053_job_locks.sql
-- ============================================================================
-- ============================================================================
-- 053_job_locks.sql — Scheduled jobs run on ONE API instance at a time.
--
-- With several API instances every @Cron job would run on each of them: duplicate reminder
-- notifications, duplicate alerts, two payouts reconciling the same withdrawal at once.
-- try_acquire_job_lock() is an atomic "lease": the first instance to ask gets it for
-- p_ttl_seconds, the others get false until it expires. Nothing needs releasing — set the
-- lease slightly shorter than the job's period and the next period is free again; if the
-- instance dies, the lease just runs out.
--
-- API only (no direct access from the public key). Run once in the Supabase SQL editor (after 052).
-- ============================================================================

CREATE TABLE IF NOT EXISTS job_locks (
  name TEXT PRIMARY KEY,
  locked_until TIMESTAMPTZ NOT NULL,
  locked_by TEXT,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE job_locks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON job_locks FROM PUBLIC, anon, authenticated;
GRANT ALL ON job_locks TO service_role;

CREATE OR REPLACE FUNCTION public.try_acquire_job_lock(p_name TEXT, p_ttl_seconds INT, p_owner TEXT)
RETURNS BOOLEAN
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_got TEXT;
BEGIN
  IF p_ttl_seconds < 1 OR p_ttl_seconds > 86400 THEN RAISE EXCEPTION 'JOB_LOCK_INVALID_TTL'; END IF;

  -- Takes the row if it doesn't exist, or if the previous lease has expired. Atomic: two
  -- instances asking at the same instant cannot both get it.
  INSERT INTO job_locks AS l (name, locked_until, locked_by)
  VALUES (p_name, NOW() + make_interval(secs => p_ttl_seconds), p_owner)
  ON CONFLICT (name) DO UPDATE
    SET locked_until = EXCLUDED.locked_until, locked_by = EXCLUDED.locked_by, updated_at = NOW()
    WHERE l.locked_until <= NOW()
  RETURNING l.name INTO v_got;

  RETURN v_got IS NOT NULL;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.try_acquire_job_lock(TEXT, INT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.try_acquire_job_lock(TEXT, INT, TEXT) TO service_role;

-- ============================================================================
-- 054_device_integrity.sql
-- ============================================================================
-- ============================================================================
-- 054_device_integrity.sql — Is the phone running the app trustworthy?
--
-- The Android app asks Google Play Integrity to vouch for (a) the app (genuine, unmodified,
-- signed by us) and (b) the device (certified, not rooted / emulated / bootloader-unlocked), and
-- sends the signed verdict to the API, which verifies it with Google and records the outcome here.
-- DEVICE_INTEGRITY_MODE (off | warn | enforce) decides what the API does with it: money leaving
-- a wallet from an Android-app session needs a recent TRUSTED verdict when it is "enforce".
--
-- profiles.active_client_platform remembers where the current session was opened (android-app,
-- web…), set at login by the API, so the rule follows the SESSION rather than a header an attacker
-- who replays a stolen token could simply leave out.
--
-- API only. Run once in the Supabase SQL editor (after 053).
-- ============================================================================

CREATE TABLE IF NOT EXISTS device_attestations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  status TEXT NOT NULL CHECK (status IN ('trusted', 'untrusted')),
  -- Why it is untrusted (device_not_certified, app_not_recognized, client_reports_root, …).
  reasons TEXT[] NOT NULL DEFAULT '{}',
  -- What the app's own checks saw (su_binary, test_keys, …): advisory — a rooted device can lie.
  client_signals TEXT[] NOT NULL DEFAULT '{}',
  app_version TEXT,
  -- Hash of the one-time challenge: the same signed verdict can't be replayed.
  nonce_hash TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_device_attestations_user ON device_attestations(user_id, created_at DESC);

ALTER TABLE device_attestations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON device_attestations FROM PUBLIC, anon, authenticated;
GRANT ALL ON device_attestations TO service_role;

ALTER TABLE profiles ADD COLUMN IF NOT EXISTS active_client_platform TEXT;

-- ============================================================================
-- 055_atomic_attempts_and_token_revocation.sql
-- ============================================================================
-- ============================================================================
-- 055_atomic_attempts_and_token_revocation.sql — fixes found in the security review.
--
-- 1. Lockouts that a burst of parallel guesses could not slip past.
--    Until now: check "is it locked?" → verify the password / code / PIN → record the failure.
--    N requests sent at the same instant ALL passed the check before the first failure was written,
--    so an attacker got N guesses instead of 5. reserve_*() counts the attempt BEFORE it is verified,
--    under a row lock; the attempt that reaches the limit locks the account at once, so the requests
--    behind it are refused. A successful attempt clears the counter (clear_auth_attempts /
--    clear_pin_attempts), so a legitimate user's last allowed try is never held against them.
--
-- 2. Revoking administrator sessions. Administrators are exempt from the single-active-session rule,
--    so logging out, "reset session" or a 2FA reset did not invalidate a stolen token. A token now
--    dies when it was issued before profiles.tokens_valid_after (the API bumps it on those actions).
--
-- API only. Run once in the Supabase SQL editor (after 054).
-- ============================================================================

ALTER TABLE profiles ADD COLUMN IF NOT EXISTS tokens_valid_after TIMESTAMPTZ;

-- ---------------------------------------------------------------- login / 2FA / app-code style counters
CREATE OR REPLACE FUNCTION public.reserve_auth_attempt(
  p_key TEXT,
  p_max INT,
  p_window_seconds INT,
  p_lock_seconds INT
) RETURNS TABLE (allowed BOOLEAN, locked_until TIMESTAMPTZ, just_locked BOOLEAN)
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_now TIMESTAMPTZ := clock_timestamp();
  v_row auth_attempts;
BEGIN
  INSERT INTO auth_attempts (key, failures, window_started_at) VALUES (p_key, 0, v_now)
  ON CONFLICT (key) DO NOTHING;

  SELECT * INTO v_row FROM auth_attempts WHERE key = p_key FOR UPDATE;

  -- Already locked: this attempt is refused, and does not extend the lock.
  IF v_row.locked_until IS NOT NULL AND v_row.locked_until > v_now THEN
    RETURN QUERY SELECT FALSE, v_row.locked_until, FALSE;
    RETURN;
  END IF;

  IF v_row.window_started_at < v_now - make_interval(secs => p_window_seconds) THEN
    v_row.failures := 0;
    v_row.window_started_at := v_now;
  END IF;

  v_row.failures := v_row.failures + 1;

  IF v_row.failures >= p_max THEN
    -- This is the last attempt that is allowed: it proceeds, and anything behind it is refused.
    UPDATE auth_attempts
       SET failures = 0, window_started_at = v_now, locked_until = v_now + make_interval(secs => p_lock_seconds)
     WHERE key = p_key
    RETURNING auth_attempts.locked_until INTO v_row.locked_until;
    RETURN QUERY SELECT TRUE, v_row.locked_until, TRUE;
  ELSE
    UPDATE auth_attempts SET failures = v_row.failures, window_started_at = v_row.window_started_at WHERE key = p_key;
    RETURN QUERY SELECT TRUE, NULL::TIMESTAMPTZ, FALSE;
  END IF;
END;
$$ LANGUAGE plpgsql;

-- Gives an attempt back (it failed for a reason that isn't the user's fault: the auth provider was rate-limiting, say).
CREATE OR REPLACE FUNCTION public.release_auth_attempt(p_key TEXT)
RETURNS VOID
SECURITY DEFINER
SET search_path = public
AS $$
  UPDATE auth_attempts SET failures = GREATEST(failures - 1, 0) WHERE key = p_key AND (locked_until IS NULL OR locked_until <= clock_timestamp())
$$ LANGUAGE sql;

-- ---------------------------------------------------------------- transaction PIN
CREATE OR REPLACE FUNCTION public.reserve_pin_attempt(
  p_user UUID,
  p_max INT,
  p_lock_seconds INT
) RETURNS TABLE (has_pin BOOLEAN, allowed BOOLEAN, locked_until TIMESTAMPTZ, just_locked BOOLEAN, attempts INT)
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_now TIMESTAMPTZ := clock_timestamp();
  v_p RECORD;
  v_attempts INT;
BEGIN
  SELECT transaction_pin_hash, pin_attempts, pin_locked_until INTO v_p FROM profiles WHERE id = p_user FOR UPDATE;
  IF NOT FOUND OR v_p.transaction_pin_hash IS NULL THEN
    RETURN QUERY SELECT FALSE, FALSE, NULL::TIMESTAMPTZ, FALSE, 0;
    RETURN;
  END IF;

  IF v_p.pin_locked_until IS NOT NULL AND v_p.pin_locked_until > v_now THEN
    RETURN QUERY SELECT TRUE, FALSE, v_p.pin_locked_until, FALSE, COALESCE(v_p.pin_attempts, 0);
    RETURN;
  END IF;

  v_attempts := COALESCE(v_p.pin_attempts, 0) + 1;
  IF v_attempts >= p_max THEN
    UPDATE profiles SET pin_attempts = 0, pin_locked_until = v_now + make_interval(secs => p_lock_seconds) WHERE id = p_user
    RETURNING profiles.pin_locked_until INTO v_p.pin_locked_until;
    RETURN QUERY SELECT TRUE, TRUE, v_p.pin_locked_until, TRUE, p_max;
  ELSE
    UPDATE profiles SET pin_attempts = v_attempts, pin_locked_until = NULL WHERE id = p_user;
    RETURN QUERY SELECT TRUE, TRUE, NULL::TIMESTAMPTZ, FALSE, v_attempts;
  END IF;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.clear_pin_attempts(p_user UUID)
RETURNS VOID
SECURITY DEFINER
SET search_path = public
AS $$
  UPDATE profiles SET pin_attempts = 0, pin_locked_until = NULL WHERE id = p_user
$$ LANGUAGE sql;

DO $$
DECLARE f TEXT;
BEGIN
  FOREACH f IN ARRAY ARRAY[
    'reserve_auth_attempt(TEXT, INT, INT, INT)',
    'release_auth_attempt(TEXT)',
    'reserve_pin_attempt(UUID, INT, INT)',
    'clear_pin_attempts(UUID)'
  ] LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION public.%s FROM PUBLIC, anon, authenticated', f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION public.%s TO service_role', f);
  END LOOP;
END $$;

-- ============================================================================
-- 056_atomic_topup_completion.sql
-- ============================================================================
-- ============================================================================
-- 056_atomic_topup_completion.sql — a top-up is credited exactly once.
--
-- A card/Mobile-Money top-up can be confirmed from several places at the same moment: the PSP webhook
-- (possibly delivered twice) and the status check the app makes when the user comes back from the payment
-- page. The webhook path used to read the status, credit the wallet, and only then mark the top-up SUCCESS:
-- two confirmations racing each other both read "not SUCCESS yet" and both credited. And when the credit
-- failed after the status had been claimed, the user's payment was never credited at all.
--
-- complete_topup() does it in ONE transaction under a row lock: the first caller credits the wallet and marks
-- the top-up SUCCESS; every later (or concurrent) caller finds it already SUCCESS and does nothing; if the
-- credit fails, nothing is claimed and the top-up stays PENDING, so the next confirmation can retry.
--
-- API only. Run once in the Supabase SQL editor (after 055).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.complete_topup(p_topup_id UUID, p_psp_intent_id TEXT DEFAULT NULL)
RETURNS TABLE (credited BOOLEAN, user_id UUID, amount_cents BIGINT, currency VARCHAR)
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_t wallet_topups;
  v_user UUID;
BEGIN
  SELECT * INTO v_t FROM wallet_topups WHERE id = p_topup_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'TOPUP_NOT_FOUND'; END IF;

  SELECT w.user_id INTO v_user FROM wallets w WHERE w.id = v_t.wallet_id;

  IF v_t.status = 'SUCCESS' THEN
    RETURN QUERY SELECT FALSE, v_user, v_t.amount_cents, v_t.currency;
    RETURN;
  END IF;

  -- Belt and braces: never credit a top-up that already has its ledger entry (a status that was lost after a credit).
  IF NOT EXISTS (
    SELECT 1 FROM ledger_entries l
     WHERE l.wallet_id = v_t.wallet_id AND l.reference = 'TOPUP-' || v_t.id AND l.entry_type = 'TOPUP'
  ) THEN
    PERFORM credit_wallet(v_t.wallet_id, v_t.amount_cents, 'TOPUP', 'TOPUP-' || v_t.id, v_t.currency,
      jsonb_build_object('wallet_topup_id', v_t.id, 'psp_intent_id', p_psp_intent_id));
  END IF;

  UPDATE wallet_topups SET status = 'SUCCESS', updated_at = NOW() WHERE id = v_t.id;
  RETURN QUERY SELECT TRUE, v_user, v_t.amount_cents, v_t.currency;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.complete_topup(UUID, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.complete_topup(UUID, TEXT) TO service_role;

-- ============================================================================
-- 057_atomic_withdrawal_request.sql
-- ============================================================================
-- ============================================================================
-- 057_atomic_withdrawal_request.sql — a withdrawal request and its debit happen together, or not at all.
--
-- Until now: INSERT the withdrawal (PENDING), then — as a separate call — debit the wallet. A crash or a
-- deploy between the two left a PENDING withdrawal that was never debited. Ten minutes later the payout
-- reconciliation found the provider knew nothing of it and "reversed" it: fail_withdrawal() credited the
-- wallet amount + fee that had never been taken — money created from nothing. Conversely a timeout on the
-- debit call (committed on the database, unknown to the API) was read as "insufficient balance": the
-- withdrawal was marked FAILED, never REVERSED, and the user's debit was never given back.
--
-- request_withdrawal() inserts and debits in ONE transaction (nothing exists if the balance is short), and
-- fail_withdrawal() only gives money back when a debit for this withdrawal really exists in the ledger.
--
-- API only. Run once in the Supabase SQL editor (after 056).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.request_withdrawal(
  p_wallet UUID,
  p_amount BIGINT,
  p_fee BIGINT,
  p_currency VARCHAR,
  p_channel TEXT,
  p_destination JSONB,
  p_psp_provider TEXT,
  p_idempotency_key TEXT
) RETURNS withdrawals
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_w withdrawals;
BEGIN
  IF p_amount < 1 OR p_fee < 0 THEN RAISE EXCEPTION 'WITHDRAWAL_INVALID_AMOUNT'; END IF;

  INSERT INTO withdrawals (wallet_id, amount_cents, fee_cents, currency, channel, destination, status, psp_provider, idempotency_key)
  VALUES (p_wallet, p_amount, p_fee, p_currency, p_channel, p_destination, 'PENDING', p_psp_provider, p_idempotency_key)
  RETURNING * INTO v_w;

  -- Raises 'Insufficient balance' when the wallet doesn't hold amount + fee: the INSERT above is rolled back with it.
  PERFORM debit_wallet(p_wallet, p_amount + p_fee, 'WITHDRAWAL', 'WITHDRAWAL-' || v_w.id, p_currency,
    jsonb_build_object('withdrawal_id', v_w.id, 'channel', p_channel));

  RETURN v_w;
END;
$$ LANGUAGE plpgsql;

-- Give the money back ONLY if it was taken. A withdrawal with no debit in the ledger is simply closed as failed.
CREATE OR REPLACE FUNCTION public.fail_withdrawal(
  p_withdrawal_id UUID,
  p_reason TEXT
) RETURNS withdrawals
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row withdrawals;
BEGIN
  SELECT * INTO v_row FROM withdrawals WHERE id = p_withdrawal_id FOR UPDATE;
  IF NOT FOUND OR v_row.status NOT IN ('PENDING', 'PROCESSING') THEN
    RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1 FROM ledger_entries l
     WHERE l.wallet_id = v_row.wallet_id AND l.reference = 'WITHDRAWAL-' || v_row.id
       AND l.entry_type = 'WITHDRAWAL' AND l.direction = 'debit'
  ) THEN
    PERFORM credit_wallet(
      v_row.wallet_id, v_row.amount_cents + v_row.fee_cents, 'ADJUSTMENT',
      'WITHDRAWAL-REVERSAL-' || v_row.id, v_row.currency,
      jsonb_build_object('withdrawal_id', v_row.id, 'reason', p_reason)
    );
    UPDATE withdrawals SET status = 'REVERSED', failure_reason = p_reason, updated_at = NOW()
     WHERE id = p_withdrawal_id RETURNING * INTO v_row;
  ELSE
    -- Nothing was ever debited: there is nothing to give back.
    UPDATE withdrawals SET status = 'FAILED', failure_reason = p_reason, updated_at = NOW()
     WHERE id = p_withdrawal_id RETURNING * INTO v_row;
  END IF;

  RETURN v_row;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.request_withdrawal(UUID, BIGINT, BIGINT, VARCHAR, TEXT, JSONB, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.fail_withdrawal(UUID, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.request_withdrawal(UUID, BIGINT, BIGINT, VARCHAR, TEXT, JSONB, TEXT, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.fail_withdrawal(UUID, TEXT) TO service_role;

-- ============================================================================
-- 058_refund_guards.sql
-- ============================================================================
-- ============================================================================
-- 058_refund_guards.sql — refunds respect frozen wallets and unpaid transactions.
--
-- refund_to_client_wallet() (041) did not look at wallet status: a FROZEN or SUSPENDED merchant wallet could still be
-- drained to a client wallet by a refund. And a refund requested before the merchant's net had been credited turned
-- the transaction into REFUNDED, after which credit_merchant_wallet() refuses it — the merchant was never paid.
-- Both are now refused (REFUND_WALLET_NOT_ACTIVE, REFUND_TX_NOT_CREDITED).
--
-- API only. Run once in the Supabase SQL editor (after 057).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.refund_to_client_wallet(
  p_transaction_id UUID,
  p_amount_cents BIGINT,
  p_reason TEXT,
  p_processed_by UUID
) RETURNS refunds
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tx transactions;
  v_owner UUID;
  v_merchant_wallet UUID;
  v_client_wallet UUID;
  v_already BIGINT;
  v_balance BIGINT;
  v_total_refunded BIGINT;
  v_refund refunds;
BEGIN
  IF p_amount_cents <= 0 THEN
    RAISE EXCEPTION 'REFUND_INVALID_AMOUNT';
  END IF;

  SELECT * INTO v_tx FROM transactions WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'REFUND_TX_NOT_FOUND';
  END IF;

  IF v_tx.status NOT IN ('SUCCESS', 'PARTIALLY_REFUNDED') THEN
    RAISE EXCEPTION 'REFUND_TX_NOT_REFUNDABLE';
  END IF;

  -- The merchant's net must have reached their wallet first. Refunding before that would flip the transaction to
  -- REFUNDED, and credit_merchant_wallet() refuses a refunded transaction: the merchant would never be paid.
  IF v_tx.wallet_credited_at IS NULL THEN
    RAISE EXCEPTION 'REFUND_TX_NOT_CREDITED';
  END IF;

  -- Paid out the old way (manual settlement): the money already left the
  -- platform for the merchant, so it can't be clawed back from a wallet.
  IF v_tx.settlement_id IS NOT NULL THEN
    RAISE EXCEPTION 'REFUND_TX_SETTLED';
  END IF;

  IF v_tx.client_id IS NULL THEN
    RAISE EXCEPTION 'REFUND_NO_CLIENT_ACCOUNT';
  END IF;

  SELECT COALESCE(SUM(amount_cents), 0) INTO v_already
    FROM refunds WHERE transaction_id = p_transaction_id AND status IN ('PENDING', 'COMPLETED');
  IF v_already + p_amount_cents > v_tx.amount_cents THEN
    RAISE EXCEPTION 'REFUND_EXCEEDS_AMOUNT';
  END IF;

  SELECT owner_id INTO v_owner FROM merchants WHERE id = v_tx.merchant_id;
  SELECT id INTO v_merchant_wallet FROM wallets WHERE user_id = v_owner;
  SELECT id INTO v_client_wallet FROM wallets WHERE user_id = v_tx.client_id;

  IF v_client_wallet IS NULL THEN
    RAISE EXCEPTION 'REFUND_NO_CLIENT_ACCOUNT';
  END IF;
  IF v_merchant_wallet IS NULL THEN
    RAISE EXCEPTION 'REFUND_INSUFFICIENT_BALANCE:0:%', p_amount_cents;
  END IF;

  -- A frozen or suspended wallet is frozen for a reason: money must not leave it (or enter it) through a refund.
  IF EXISTS (SELECT 1 FROM wallets WHERE id IN (v_merchant_wallet, v_client_wallet) AND status <> 'ACTIVE') THEN
    RAISE EXCEPTION 'REFUND_WALLET_NOT_ACTIVE';
  END IF;

  -- Always lock the two wallets in the same order, or two refunds going in
  -- opposite directions could deadlock each other.
  PERFORM 1 FROM wallets WHERE id IN (v_merchant_wallet, v_client_wallet) ORDER BY id FOR UPDATE;

  SELECT COALESCE(SUM(CASE WHEN direction = 'credit' THEN amount_cents ELSE -amount_cents END), 0)
    INTO v_balance
    FROM ledger_entries WHERE wallet_id = v_merchant_wallet AND currency = v_tx.currency;

  IF v_balance < p_amount_cents THEN
    RAISE EXCEPTION 'REFUND_INSUFFICIENT_BALANCE:%:%', v_balance, p_amount_cents;
  END IF;

  INSERT INTO refunds (transaction_id, amount_cents, currency, reason, status, processed_by)
  VALUES (p_transaction_id, p_amount_cents, v_tx.currency, p_reason, 'COMPLETED', p_processed_by)
  RETURNING * INTO v_refund;

  PERFORM debit_wallet(v_merchant_wallet, p_amount_cents, 'REFUND', 'REFUND-' || v_refund.id, v_tx.currency,
    jsonb_build_object('refund_id', v_refund.id, 'transaction_id', v_tx.id, 'direction', 'refund_given'));
  PERFORM credit_wallet(v_client_wallet, p_amount_cents, 'REFUND', 'REFUND-' || v_refund.id, v_tx.currency,
    jsonb_build_object('refund_id', v_refund.id, 'transaction_id', v_tx.id, 'direction', 'refund_received'));

  INSERT INTO ledger_entries (transaction_id, entry_type, direction, amount_cents, currency, reference, source, metadata)
  VALUES (v_tx.id, 'REFUND', 'debit', p_amount_cents, v_tx.currency, v_tx.reference, 'system',
          jsonb_build_object('refund_id', v_refund.id));

  SELECT COALESCE(SUM(amount_cents), 0) INTO v_total_refunded
    FROM refunds WHERE transaction_id = p_transaction_id AND status = 'COMPLETED';

  UPDATE transactions
     SET status = CASE WHEN v_total_refunded >= v_tx.amount_cents THEN 'REFUNDED' ELSE 'PARTIALLY_REFUNDED' END::transaction_status,
         updated_at = NOW()
   WHERE id = p_transaction_id;

  RETURN v_refund;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.refund_to_client_wallet(UUID, BIGINT, TEXT, UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.refund_to_client_wallet(UUID, BIGINT, TEXT, UUID) TO service_role;

-- ============================================================================
-- 059_cards.sql
-- ============================================================================
-- ============================================================================
-- 059_cards.sql — The ScanLinkPay card.
--
-- One physical card per person (client, merchant, boss, employee…), printed by a
-- super admin, tied to the person's own wallet. Life of a card:
--
--   requested  the person asked for one in the app (optional: an admin can also
--              issue a card straight from the person's ScanLinkPay number)
--   issued     number and QR code are generated, the card is printed — NOT usable yet
--   active     the holder activated it in the app (card number + PIN): proves they
--              really hold the card. A card handed to the wrong person is useless.
--   frozen     the holder paused it (they can unfreeze it with their PIN)
--   blocked    lost / stolen / cancelled by an admin: final, a new card is issued
--   replaced   superseded by a newer card
--
-- The card holds NO balance and NO secret: the QR code is only an opaque token that
-- designates the card, and every payment still needs the holder's wallet PIN. The
-- card number is a 16-digit ISO/IEC 7812 number (Luhn check digit), different from
-- the wallet number: losing a card never changes the number everybody uses to pay you.
--
-- Paying: a merchant scans the card, creates a charge (card_charges) bound to a normal
-- payment request, the holder approves it in their app with the PIN, and the existing
-- wallet payment does the rest. A charge expires after a few minutes.
--
-- Everything here is for the API only (no direct access from the public key).
-- Run once in the Supabase SQL editor (after 058).
-- ============================================================================

CREATE TABLE IF NOT EXISTS cards (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  -- Printed on the signature panel as "Réf." so a card can be found from its print-out.
  serial_no BIGINT GENERATED ALWAYS AS IDENTITY,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  wallet_id UUID NOT NULL REFERENCES wallets(id),
  status TEXT NOT NULL DEFAULT 'requested'
    CHECK (status IN ('requested', 'issued', 'active', 'frozen', 'blocked', 'replaced')),
  -- Filled when the card is issued.
  card_number VARCHAR(16) UNIQUE CHECK (card_number IS NULL OR card_number ~ '^[0-9]{16}$'),
  qr_token VARCHAR(24) UNIQUE,
  holder_name TEXT,
  expires_on DATE,
  issued_at TIMESTAMPTZ,
  issued_by UUID REFERENCES auth.users(id),
  print_count INT NOT NULL DEFAULT 0,
  activated_at TIMESTAMPTZ,
  blocked_at TIMESTAMPTZ,
  blocked_reason TEXT,
  replaced_by UUID REFERENCES cards(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT cards_issued_has_number CHECK (
    status IN ('requested', 'blocked', 'replaced') OR (card_number IS NOT NULL AND qr_token IS NOT NULL AND expires_on IS NOT NULL)
  )
);
-- ONE living card per person: requested / issued / active / frozen. Blocked and replaced cards are history.
CREATE UNIQUE INDEX IF NOT EXISTS uniq_cards_one_live_per_user
  ON cards(user_id) WHERE status IN ('requested', 'issued', 'active', 'frozen');
CREATE INDEX IF NOT EXISTS idx_cards_status ON cards(status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_cards_wallet ON cards(wallet_id);

CREATE TABLE IF NOT EXISTS card_charges (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  card_id UUID NOT NULL REFERENCES cards(id),
  merchant_id UUID NOT NULL REFERENCES merchants(id),
  payment_request_id UUID NOT NULL REFERENCES payment_requests(id),
  created_by UUID REFERENCES auth.users(id),
  amount_cents BIGINT NOT NULL CHECK (amount_cents > 0),
  currency VARCHAR(10) NOT NULL,
  -- pending → processing (the holder approved, the payment is running) → approved | pending again if the
  -- payment did not go through (wrong PIN, not enough money). declined / expired / cancelled are final.
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'processing', 'approved', 'declined', 'expired', 'cancelled')),
  expires_at TIMESTAMPTZ NOT NULL,
  decided_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_card_charges_card ON card_charges(card_id, status);
CREATE INDEX IF NOT EXISTS idx_card_charges_merchant ON card_charges(merchant_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uniq_card_charges_request ON card_charges(payment_request_id);

-- What the super admin decides: the contact printed on the back, the domain of the QR code,
-- how long a card is valid, the logos of the partners shown on the back.
CREATE TABLE IF NOT EXISTS card_settings (
  id INT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  service_phone TEXT,
  -- Printed on the back as the line to call when a card is lost or stolen.
  lost_card_phone TEXT,
  web_domain TEXT,
  validity_years INT NOT NULL DEFAULT 3 CHECK (validity_years BETWEEN 1 AND 10),
  -- [{ "name": "Orange Money", "image": "data:image/png;base64,..." }] — checked by the API (type, size, count).
  partner_logos JSONB NOT NULL DEFAULT '[]'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_by UUID REFERENCES auth.users(id)
);
ALTER TABLE card_settings ADD COLUMN IF NOT EXISTS lost_card_phone TEXT;
INSERT INTO card_settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING;

DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['cards', 'card_charges', 'card_settings']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('REVOKE ALL ON %I FROM PUBLIC, anon, authenticated', t);
    EXECUTE format('GRANT ALL ON %I TO service_role', t);
  END LOOP;
END $$;

-- ----------------------------------------------------------------------------
-- issue_card: turn a request (or nothing) into an issued card, atomically.
--   * the person already has a request          → that request becomes the issued card
--   * the person has a card and p_replace       → the old one is 'replaced', a new one is issued
--   * the person has a card and NOT p_replace   → CARD_ALREADY_EXISTS
-- A number or token collision raises unique_violation: the API retries with new values.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.issue_card(
  p_user UUID,
  p_wallet UUID,
  p_holder_name TEXT,
  p_card_number VARCHAR,
  p_qr_token VARCHAR,
  p_expires_on DATE,
  p_admin UUID,
  p_replace BOOLEAN
) RETURNS SETOF cards
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_live cards;
  v_new cards;
BEGIN
  PERFORM 1 FROM wallets WHERE id = p_wallet AND user_id = p_user;
  IF NOT FOUND THEN RAISE EXCEPTION 'CARD_WALLET_MISMATCH'; END IF;

  SELECT * INTO v_live FROM cards
   WHERE user_id = p_user AND status IN ('requested', 'issued', 'active', 'frozen')
   FOR UPDATE;

  IF FOUND AND v_live.status = 'requested' THEN
    UPDATE cards
       SET status = 'issued', card_number = p_card_number, qr_token = p_qr_token, holder_name = p_holder_name,
           expires_on = p_expires_on, issued_at = NOW(), issued_by = p_admin, updated_at = NOW()
     WHERE id = v_live.id
     RETURNING * INTO v_new;
    RETURN NEXT v_new;
    RETURN;
  END IF;

  IF FOUND THEN
    IF NOT p_replace THEN RAISE EXCEPTION 'CARD_ALREADY_EXISTS'; END IF;
    UPDATE cards SET status = 'replaced', blocked_at = NOW(), blocked_reason = 'replaced', updated_at = NOW() WHERE id = v_live.id;
    -- Anything the old card was about to charge is void.
    UPDATE card_charges SET status = 'cancelled', decided_at = NOW() WHERE card_id = v_live.id AND status IN ('pending', 'processing');
  END IF;

  INSERT INTO cards (user_id, wallet_id, status, card_number, qr_token, holder_name, expires_on, issued_at, issued_by)
  VALUES (p_user, p_wallet, 'issued', p_card_number, p_qr_token, p_holder_name, p_expires_on, NOW(), p_admin)
  RETURNING * INTO v_new;
  IF v_live.id IS NOT NULL THEN
    UPDATE cards SET replaced_by = v_new.id WHERE id = v_live.id;
  END IF;
  RETURN NEXT v_new;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.issue_card(UUID, UUID, TEXT, VARCHAR, VARCHAR, DATE, UUID, BOOLEAN) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.issue_card(UUID, UUID, TEXT, VARCHAR, VARCHAR, DATE, UUID, BOOLEAN) TO service_role;

-- ============================================================================
-- 060_flexpaie_orders.sql
-- ============================================================================
-- ============================================================================
-- 060_flexpaie_orders.sql — FlexPaie payments: our reference <-> their order number.
--
-- FlexPaie answers a payment request with an "orderNumber" and can only be asked about a payment by that number
-- (GET /api/rest/v1/check/<orderNumber>). Everywhere else in ScanLinkPay a payment is found by OUR reference
-- (the one carried in the return link and stored as psp_intent_id), so this table remembers which order number
-- belongs to which reference. It is also what keeps a forged callback harmless: the status of a payment is always
-- read from FlexPaie with the order number recorded HERE, never with one found in the callback.
--
-- API only. Run once in the Supabase SQL editor (after 059).
-- ============================================================================

CREATE TABLE IF NOT EXISTS flexpaie_orders (
  reference TEXT PRIMARY KEY,
  order_number TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE flexpaie_orders ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON flexpaie_orders FROM PUBLIC, anon, authenticated;
GRANT ALL ON flexpaie_orders TO service_role;

-- ============================================================================
-- 061_merchant_scanlinkpay_number.sql
-- ============================================================================
-- ============================================================================
-- 061_merchant_scanlinkpay_number.sql — Unique per-merchant payment
-- identifier, same concept as the organization's ScanLinkPay number
-- (018_organization_scanlinkpay_number.sql).
--
-- Until now a standalone merchant (no organization) could only be paid two
-- ways: a per-invoice payment request, or a wallet transfer to their
-- SLP-MER-… wallet number — which bypasses the merchant payment path
-- entirely (no commission, not counted in the store's sales stats). This
-- gives every merchant a persistent, non-expiring number a customer can
-- scan (QR) or type to pay them through the real payment-request flow
-- (quick-pay), so a counter payment is a sale.
--
-- The number comes from the SAME sequence as organizations
-- (org_scanlinkpay_number_seq, format SLP-000123) — one global namespace
-- for "payable business" identifiers, so a number can never collide
-- between a store and a company. Unlike organizations (number assigned at
-- validation time, migration 028), merchants go live the moment they're
-- created (status 'active' on INSERT — see merchants.service.ts), so the
-- trigger fires BEFORE INSERT, the original 018 pattern.
-- Run once in the Supabase SQL editor, same as previous migrations.
-- ============================================================================

ALTER TABLE merchants
  ADD COLUMN IF NOT EXISTS scanlinkpay_number VARCHAR(20) UNIQUE,
  ADD COLUMN IF NOT EXISTS scanlinkpay_qr_url TEXT;

DROP TRIGGER IF EXISTS trg_set_scanlinkpay_number ON merchants;
CREATE TRIGGER trg_set_scanlinkpay_number
  BEFORE INSERT ON merchants
  FOR EACH ROW
  EXECUTE FUNCTION public.set_scanlinkpay_number();

-- Backfill: every merchant created before this migration gets a number too.
UPDATE merchants
SET scanlinkpay_number = public.generate_scanlinkpay_number()
WHERE scanlinkpay_number IS NULL;

-- ============================================================================
-- 062_funded_transfers.sql
-- ============================================================================
-- ============================================================================
-- 062_funded_transfers.sql — Person-to-person transfers funded by the PSP
-- (Mobile Money / card), not by the sender's wallet balance.
--
-- Run once in the Supabase SQL editor, same as previous migrations.
--
-- Why a separate completion path: transfer_wallet() (007) debits the sender's
-- wallet. A PSP-funded transfer never touches the sender's wallet — the money
-- comes in from outside (FlexPaie), so settling it only credits the recipient.
-- Like complete_topup() (056), complete_funded_transfer() claims PENDING ->
-- SUCCESS under a row lock, so a webhook delivered twice, or racing the
-- status-check endpoint, credits the recipient exactly once.
-- ============================================================================

-- Which provider funded the transfer, and the reference it knows it by
-- (used by the webhook dispatcher, the status check and the reconciliation
-- sweep — all look a funded transfer up by psp_intent_id).
ALTER TABLE transfers ADD COLUMN IF NOT EXISTS psp_provider VARCHAR(50);
ALTER TABLE transfers ADD COLUMN IF NOT EXISTS psp_intent_id VARCHAR(255);
CREATE UNIQUE INDEX IF NOT EXISTS idx_transfers_psp_intent
  ON transfers(psp_intent_id) WHERE psp_intent_id IS NOT NULL;

-- ----------------------------------------------------------------------------
-- complete_funded_transfer — settles a PSP-funded P2P transfer in ONE
-- transaction: claims PENDING -> SUCCESS, credits the recipient, returns the
-- parties so the caller can notify them. Never debits the sender's wallet
-- (the PSP already collected amount + fee from the sender's Mobile Money /
-- card — the platform fee stays in the PSP float, recorded as fee_cents).
-- SECURITY DEFINER + service_role-only, same posture as the other money RPCs.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.complete_funded_transfer(p_transfer_id UUID, p_psp_intent_id TEXT DEFAULT NULL)
RETURNS TABLE (credited BOOLEAN, sender_user_id UUID, recipient_user_id UUID, amount_cents BIGINT, currency VARCHAR)
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_transfer RECORD;
  v_recipient_status VARCHAR;
  v_sender_user UUID;
  v_recipient_user UUID;
BEGIN
  SELECT * INTO v_transfer FROM transfers WHERE id = p_transfer_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'FUNDED_TRANSFER_NOT_FOUND: %', p_transfer_id;
  END IF;
  IF v_transfer.status <> 'PENDING' THEN
    -- Someone else already settled (or failed) it — safe no-op, never a double credit.
    credited := FALSE;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT status INTO v_recipient_status FROM wallets WHERE id = v_transfer.recipient_wallet_id;
  IF v_recipient_status IS NULL OR v_recipient_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'RECIPIENT_WALLET_%', COALESCE(v_recipient_status, 'NOT_FOUND');
  END IF;

  INSERT INTO ledger_entries (wallet_id, entry_type, direction, amount_cents, currency, reference, source, metadata)
  VALUES (
    v_transfer.recipient_wallet_id, 'TRANSFER_IN', 'credit', v_transfer.amount_cents,
    v_transfer.currency, 'TRANSFER-' || v_transfer.id, 'system',
    jsonb_build_object('transfer_id', v_transfer.id, 'counterparty_wallet_id', v_transfer.sender_wallet_id, 'funded_by', COALESCE(v_transfer.psp_provider, 'psp'))
  );

  UPDATE transfers
    SET status = 'SUCCESS',
        psp_intent_id = COALESCE(p_psp_intent_id, psp_intent_id),
        updated_at = NOW()
    WHERE id = p_transfer_id;

  SELECT user_id INTO v_sender_user FROM wallets WHERE id = v_transfer.sender_wallet_id;
  SELECT user_id INTO v_recipient_user FROM wallets WHERE id = v_transfer.recipient_wallet_id;

  credited := TRUE;
  sender_user_id := v_sender_user;
  recipient_user_id := v_recipient_user;
  amount_cents := v_transfer.amount_cents;
  currency := v_transfer.currency;
  RETURN NEXT;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.complete_funded_transfer(UUID, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.complete_funded_transfer(UUID, TEXT) TO service_role;

-- ============================================================================
-- 063_staff_stations.sql
-- ============================================================================
-- ============================================================================
-- 063_staff_stations.sql — Stations (the organization's stores) and the
-- station manager role.
--
-- An organization's stores (merchants.organization_id) are its "stations".
-- Every enterprise staff member now works in ONE station
-- (organization_staff.merchant_id): the API reads it into the token as
-- station_id and only lets that person reach that station's till, stock,
-- tickets, sessions and transactions. The owner keeps every station.
--
-- New role 'gerant' (station manager): runs one station — its dashboard,
-- transactions, staff (except other managers) — and may pay the
-- organization's subscription.
--
-- Run once in the Supabase SQL editor, same as previous migrations.
-- ============================================================================

ALTER TABLE organization_staff
  ADD COLUMN IF NOT EXISTS merchant_id UUID REFERENCES merchants(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS idx_organization_staff_merchant ON organization_staff(merchant_id);

-- Backfill: an organization with a single store puts all its staff there.
-- With several stores, staff stay unassigned (no station access) until the
-- owner picks their station.
UPDATE organization_staff s
   SET merchant_id = m.id
  FROM merchants m
 WHERE s.merchant_id IS NULL
   AND m.organization_id = s.organization_id
   AND (SELECT COUNT(*) FROM merchants m2 WHERE m2.organization_id = s.organization_id) = 1;

INSERT INTO roles (slug, name, description, is_system)
VALUES ('gerant', 'Gérant de station', 'Dirige une station de l''entreprise : tableau de bord, employés et caisse de sa station', false)
ON CONFLICT (slug) DO NOTHING;

-- RLS backup (the API uses the service role): an org staff member only
-- manages the stock of their own station.
CREATE OR REPLACE FUNCTION public.is_stock_manager(merchant_uuid UUID)
RETURNS BOOLEAN AS $$
  SELECT EXISTS (
    SELECT 1 FROM merchants m
    LEFT JOIN organizations o ON o.id = m.organization_id
    WHERE m.id = merchant_uuid
      AND (
        m.owner_id = auth.uid()
        OR o.owner_id = auth.uid()
        OR EXISTS (
          SELECT 1 FROM organization_staff s
          WHERE s.user_id = auth.uid()
            AND s.organization_id = m.organization_id
            AND s.merchant_id = m.id
            AND s.deactivated_at IS NULL
        )
      )
  ) OR public.is_admin()
$$ LANGUAGE SQL STABLE SECURITY DEFINER;

-- The owner, or an active station manager of the organization, pays the
-- subscription from their own wallet.
CREATE OR REPLACE FUNCTION public.purchase_subscription(
  p_org UUID,
  p_user UUID,
  p_wallet UUID,
  p_months INT,
  p_currency VARCHAR,
  p_amount BIGINT,
  p_reference TEXT
) RETURNS TABLE (expires_at TIMESTAMPTZ)
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_existing subscription_purchases;
  v_start TIMESTAMPTZ;
  v_end TIMESTAMPTZ;
BEGIN
  IF p_months < 1 OR p_months > 24 THEN RAISE EXCEPTION 'SUBSCRIPTION_INVALID_MONTHS'; END IF;
  IF p_amount <= 0 THEN RAISE EXCEPTION 'SUBSCRIPTION_INVALID_AMOUNT'; END IF;

  PERFORM 1 FROM organizations WHERE id = p_org AND owner_id = p_user;
  IF NOT FOUND THEN
    PERFORM 1 FROM organization_staff s
      JOIN user_roles ur ON ur.user_id = s.user_id AND ur.organization_id = s.organization_id
      JOIN roles r ON r.id = ur.role_id AND r.slug = 'gerant'
     WHERE s.organization_id = p_org AND s.user_id = p_user AND s.deactivated_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'SUBSCRIPTION_NOT_OWNER'; END IF;
  END IF;
  PERFORM 1 FROM wallets WHERE id = p_wallet AND user_id = p_user;
  IF NOT FOUND THEN RAISE EXCEPTION 'WALLET_USER_MISMATCH'; END IF;

  INSERT INTO organization_subscriptions (organization_id) VALUES (p_org) ON CONFLICT (organization_id) DO NOTHING;
  SELECT GREATEST(COALESCE(s.expires_at, NOW()), NOW()) INTO v_start
    FROM organization_subscriptions s WHERE s.organization_id = p_org FOR UPDATE;

  SELECT * INTO v_existing FROM subscription_purchases WHERE reference = p_reference;
  IF FOUND THEN
    IF v_existing.organization_id <> p_org THEN RAISE EXCEPTION 'SUBSCRIPTION_REFERENCE_CONFLICT'; END IF;
    RETURN QUERY SELECT v_existing.expires_at;
    RETURN;
  END IF;
  v_end := v_start + make_interval(months => p_months);

  PERFORM debit_wallet(p_wallet, p_amount, 'SUBSCRIPTION', 'SUBSCRIPTION-' || p_reference, p_currency,
    jsonb_build_object('organization_id', p_org, 'months', p_months));

  INSERT INTO subscription_purchases (organization_id, purchased_by, months, currency, amount_cents, reference, starts_at, expires_at)
  VALUES (p_org, p_user, p_months, p_currency, p_amount, p_reference, v_start, v_end);

  UPDATE organization_subscriptions s
     SET expires_at = v_end, last_reminder_days = NULL, updated_at = NOW()
   WHERE s.organization_id = p_org;

  RETURN QUERY SELECT v_end;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.purchase_subscription(UUID, UUID, UUID, INT, VARCHAR, BIGINT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.purchase_subscription(UUID, UUID, UUID, INT, VARCHAR, BIGINT, TEXT) TO service_role;

-- ============================================================================
-- 064_stock_password_optional.sql
-- ============================================================================
-- ============================================================================
-- 064_stock_password_optional.sql — The stock management password becomes an
-- option the owner switches on or off (off by default).
--
-- Off: only the role counts — the owner and the stock keeper change the
-- stock, everyone else reads it; every change stays in the audit journal.
-- On: the shared password is asked as before (adding/editing/removing an
-- article, a movement, validating an inventory, archiving a sale).
--
-- Run once in the Supabase SQL editor, same as previous migrations.
-- ============================================================================

ALTER TABLE organizations
  ADD COLUMN IF NOT EXISTS stock_password_required BOOLEAN NOT NULL DEFAULT false;

-- ============================================================================
-- 065_restock_requests.sql
-- ============================================================================
-- ============================================================================
-- 065_restock_requests.sql — Restock requests from a station to the owner.
--
-- The station manager or the stock keeper asks the owner to buy the articles
-- that run low: the owner approves or refuses, then the station marks the
-- goods as received. Each step notifies the other side.
--
-- Run once in the Supabase SQL editor, same as previous migrations.
-- ============================================================================

CREATE TABLE IF NOT EXISTS restock_requests (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  merchant_id UUID NOT NULL REFERENCES merchants(id) ON DELETE CASCADE,
  requested_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  -- [{ stock_item_id, name, current_qty, wanted_qty }]
  items JSONB NOT NULL DEFAULT '[]'::jsonb,
  note TEXT,
  status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'received')),
  decided_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  decided_at TIMESTAMPTZ,
  decision_note TEXT,
  received_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  received_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_restock_requests_org ON restock_requests(organization_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_restock_requests_merchant ON restock_requests(merchant_id, created_at DESC);

-- Only the API (service role) reads and writes it; access is checked there.
ALTER TABLE restock_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON restock_requests FROM anon, authenticated;

-- ============================================================================
-- 066_phone_login.sql
-- ============================================================================
-- ============================================================================
-- 066_phone_login.sql — Sign up and log in with the phone number; email optional.
--
-- Many people have a phone number but no email. A phone-only account gets a
-- technical email in Supabase Auth (t243XXXXXXXXX@sans-email.scanlinkpay.invalid,
-- a reserved domain nothing is ever sent to) because Auth signs in by email;
-- the profile keeps NO email for it, so the app never shows the technical one.
--
-- Without SMS, a forgotten password is recovered with a recovery code given
-- at sign-up (stored hashed here) — or by email, when the person gave one.
--
-- Run once in the Supabase SQL editor, same as previous migrations.
-- ============================================================================

-- The email becomes optional (still unique when present).
ALTER TABLE profiles ALTER COLUMN email DROP NOT NULL;

-- The auto-created profile never copies the technical email.
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, email, full_name, phone)
  VALUES (
    NEW.id,
    CASE WHEN NEW.email LIKE '%@sans-email.scanlinkpay.invalid' THEN NULL ELSE NEW.email END,
    NEW.raw_user_meta_data->>'full_name',
    NEW.raw_user_meta_data->>'phone'
  );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Recovery code (bcrypt hash, never the code itself).
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS recovery_code_hash TEXT;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS recovery_code_set_at TIMESTAMPTZ;

-- Logging in looks the account up by its phone number.
CREATE INDEX IF NOT EXISTS idx_profiles_phone ON profiles(phone);

-- ============================================================================
-- 067_flexpaie_payouts.sql
-- ============================================================================
-- ============================================================================
-- 067_flexpaie_payouts.sql — Automatic withdrawals through FlexPaie (PayoutService).
--
-- FlexPaie can only be asked about a payout by ITS order number (GET …/check/<orderNumber>), and gives that number
-- only in the answer to the send request (or later in its callback). This table is the journal of each withdrawal
-- sent to FlexPaie, written BEFORE the request leaves, so that we always know which of these is true:
--
--   SENDING   the request left (or was about to) and we have no answer yet: the money MAY have left. Never resent.
--             If FlexPaie's callback brings the order number, it is checked and the row becomes ACCEPTED; with no
--             news after 30 minutes the withdrawal is refunded and the row becomes ABANDONED.
--   ACCEPTED  FlexPaie accepted it and gave its order number: the status is read with that number.
--   NOT_SENT  FlexPaie refused it up front for a passing reason (another payout in progress): sent again later.
--   ABANDONED SENDING with no news after 30 minutes: the withdrawal was refunded.
--
-- reference = the withdrawal id. One row per withdrawal: the primary key is what stops two senders (the request and
-- the reconciliation job) from sending the same withdrawal twice.
-- sent_reference = the reference given to FlexPaie for the current attempt ("RET-<16 hex>-<attempt>", 22 to 25
-- characters, the shape of the references FlexPaie already accepts for payments). A new one per attempt, so a retry is
-- never refused as a duplicate of the attempt FlexPaie turned down; the callback is matched back with it.
-- amount_cents / currency = what was asked: an order number brought by a callback is kept only if FlexPaie's own
-- record of it carries our reference AND this amount and currency.
--
-- API only. Run once in the Supabase SQL editor (after 066), BEFORE deploying the API version that uses it.
-- ============================================================================

CREATE TABLE IF NOT EXISTS flexpaie_payouts (
  reference TEXT PRIMARY KEY,
  sent_reference TEXT UNIQUE,
  order_number TEXT UNIQUE,
  amount_cents BIGINT,
  currency TEXT,
  state TEXT NOT NULL DEFAULT 'SENDING' CHECK (state IN ('SENDING', 'ACCEPTED', 'NOT_SENT', 'ABANDONED')),
  attempts INTEGER NOT NULL DEFAULT 1,
  last_error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE flexpaie_payouts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON flexpaie_payouts FROM PUBLIC, anon, authenticated;
GRANT ALL ON flexpaie_payouts TO service_role;

-- ============================================================================
-- 068_security_hold.sql
-- ============================================================================
-- ============================================================================
-- 068_security_hold.sql — No money leaves an account for 24 h after its keys changed.
--
-- With automatic withdrawals, nobody looks at a withdrawal before the money leaves. The usual way to empty
-- somebody's account is to take it over and change its keys (password, PIN, phone number used to log in, email
-- used to reset the password) before sending the money out. So the API refuses every way money can leave an
-- account — withdrawal, transfer, wallet payment to a merchant, merchant refund — for 24 hours after one of
-- those changes (src/common/security-hold.ts). The owner, warned by the change, has time to react.
--
-- profiles.security_changed_at is stamped HERE, by triggers, so that every path counts — including the password
-- reset by email link, which never goes through the API.
--
-- Run once in the Supabase SQL editor (after 067), BEFORE deploying the API version that reads it.
-- ============================================================================

ALTER TABLE profiles ADD COLUMN IF NOT EXISTS security_changed_at TIMESTAMPTZ;

-- PIN (set or changed — a first PIN too: on an account that had none, it is exactly what someone who took the
-- account over would do before sending money out), phone number or email changed (filling in a missing one at
-- sign-up is not a change).
CREATE OR REPLACE FUNCTION public.stamp_profile_security_change()
RETURNS TRIGGER
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.transaction_pin_hash IS DISTINCT FROM OLD.transaction_pin_hash
     OR (OLD.phone IS NOT NULL AND NEW.phone IS DISTINCT FROM OLD.phone)
     OR (OLD.email IS NOT NULL AND NEW.email IS DISTINCT FROM OLD.email) THEN
    NEW.security_changed_at := NOW();
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_profiles_security_change ON profiles;
CREATE TRIGGER trg_profiles_security_change
  BEFORE UPDATE OF transaction_pin_hash, phone, email ON profiles
  FOR EACH ROW EXECUTE FUNCTION public.stamp_profile_security_change();

-- Password, login email or phone changed in Supabase Auth (by the API or by the email reset link).
CREATE OR REPLACE FUNCTION public.stamp_auth_security_change()
RETURNS TRIGGER
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF (OLD.encrypted_password IS NOT NULL AND NEW.encrypted_password IS DISTINCT FROM OLD.encrypted_password)
     OR (OLD.email IS NOT NULL AND NEW.email IS DISTINCT FROM OLD.email)
     OR (OLD.phone IS NOT NULL AND NEW.phone IS DISTINCT FROM OLD.phone) THEN
    UPDATE public.profiles SET security_changed_at = NOW() WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_auth_security_change ON auth.users;
CREATE TRIGGER trg_auth_security_change
  AFTER UPDATE OF encrypted_password, email, phone ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.stamp_auth_security_change();

REVOKE ALL ON FUNCTION public.stamp_profile_security_change() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.stamp_auth_security_change() FROM PUBLIC;

-- ============================================================================
-- 069_test_money.sql
-- ============================================================================
-- ============================================================================
-- 069_test_money.sql — No fictitious money through the app; test money only from the SQL editor, and fenced in.
--
-- The app no longer has any simulated payment provider: every top-up, payment, subscription and withdrawal is
-- real money. For tests, the developers write test money directly here (docs/RECHARGE_TEST.md):
--
--   SELECT credit_test_money('243812345678', 10000, 'CDF');   -- 10 000 CDF on that account
--   SELECT remove_test_money('243812345678', 'CDF');          -- takes all the test CDF back
--
-- The wallet is then marked is_test. Test money must never become real money, so:
--   - a test wallet can NEVER withdraw (trigger on withdrawals);
--   - a test wallet can transfer only to another test wallet (trigger on transfers);
--   - the API also refuses a wallet payment or a merchant refund from a test wallet to a real one
--     (src/common/test-money.ts);
--   - a wallet stays marked as long as it holds money (it cannot be "unmarked" with a balance).
--
-- The two functions can be run ONLY from the Supabase SQL editor (owner role): not by the API, not by any user.
-- Run once in the Supabase SQL editor (after 068), BEFORE deploying the API version that reads wallets.is_test.
-- ============================================================================

ALTER TABLE wallets ADD COLUMN IF NOT EXISTS is_test BOOLEAN NOT NULL DEFAULT false;

-- A payment intent no longer defaults to the simulated provider (the API always names the real one).
ALTER TABLE payment_intents ALTER COLUMN psp_provider DROP DEFAULT;

-- Balance of one wallet in one currency (the ledger is the source of truth).
CREATE OR REPLACE FUNCTION public.wallet_balance_cents(p_wallet UUID, p_currency TEXT)
RETURNS BIGINT
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(SUM(CASE WHEN direction = 'credit' THEN amount_cents ELSE -amount_cents END), 0)::BIGINT
    FROM ledger_entries WHERE wallet_id = p_wallet AND currency = p_currency;
$$ LANGUAGE sql STABLE;

-- ---------------------------------------------------------------------------- the fence

CREATE OR REPLACE FUNCTION public.forbid_test_wallet_withdrawal()
RETURNS TRIGGER
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM wallets WHERE id = NEW.wallet_id AND is_test) THEN
    RAISE EXCEPTION 'TEST_WALLET_WITHDRAWAL: test money cannot leave ScanLinkPay';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_forbid_test_wallet_withdrawal ON withdrawals;
CREATE TRIGGER trg_forbid_test_wallet_withdrawal
  BEFORE INSERT ON withdrawals
  FOR EACH ROW EXECUTE FUNCTION public.forbid_test_wallet_withdrawal();

CREATE OR REPLACE FUNCTION public.forbid_test_money_to_real_wallet()
RETURNS TRIGGER
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- A transfer paid by Mobile Money (psp_provider set) is real money, whoever sends it.
  IF NEW.sender_wallet_id IS NOT NULL AND NEW.psp_provider IS NULL
     AND EXISTS (SELECT 1 FROM wallets WHERE id = NEW.sender_wallet_id AND is_test)
     AND NOT EXISTS (SELECT 1 FROM wallets WHERE id = NEW.recipient_wallet_id AND is_test) THEN
    RAISE EXCEPTION 'TEST_MONEY_TO_REAL_WALLET: test money can only go to another test wallet';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_forbid_test_money_to_real_wallet ON transfers;
CREATE TRIGGER trg_forbid_test_money_to_real_wallet
  BEFORE INSERT ON transfers
  FOR EACH ROW EXECUTE FUNCTION public.forbid_test_money_to_real_wallet();

-- A test wallet stays a test wallet while it holds money (no "unmarking" to launder test money).
CREATE OR REPLACE FUNCTION public.keep_test_wallet_marked()
RETURNS TRIGGER
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF OLD.is_test AND NOT NEW.is_test
     AND (wallet_balance_cents(OLD.id, 'CDF') <> 0 OR wallet_balance_cents(OLD.id, 'USD') <> 0) THEN
    RAISE EXCEPTION 'TEST_WALLET_NOT_EMPTY: take the test money back first (remove_test_money)';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_keep_test_wallet_marked ON wallets;
CREATE TRIGGER trg_keep_test_wallet_marked
  BEFORE UPDATE OF is_test ON wallets
  FOR EACH ROW EXECUTE FUNCTION public.keep_test_wallet_marked();

-- ---------------------------------------------------------------------------- for the developers (SQL editor)

-- The account is found by its phone number (any form: +243 81…, 081…, 24381…).
CREATE OR REPLACE FUNCTION public.test_wallet_of(p_phone TEXT)
RETURNS UUID
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_digits TEXT := regexp_replace(COALESCE(p_phone, ''), '\D', '', 'g');
  v_user UUID;
  v_wallet UUID;
BEGIN
  IF v_digits LIKE '00%' THEN v_digits := substr(v_digits, 3); END IF;
  IF length(v_digits) = 10 AND v_digits LIKE '0%' THEN v_digits := '243' || substr(v_digits, 2); END IF;
  IF length(v_digits) = 9 THEN v_digits := '243' || v_digits; END IF;

  SELECT id INTO v_user FROM profiles WHERE regexp_replace(COALESCE(phone, ''), '\D', '', 'g') = v_digits LIMIT 1;
  IF v_user IS NULL THEN RAISE EXCEPTION 'No account with the phone number %', p_phone; END IF;
  SELECT id INTO v_wallet FROM wallets WHERE user_id = v_user;
  IF v_wallet IS NULL THEN RAISE EXCEPTION 'This account has no wallet yet: open the wallet in the app first'; END IF;
  RETURN v_wallet;
END;
$$ LANGUAGE plpgsql;

-- p_amount in units (10000 = 10 000 CDF, 25 = 25 USD).
CREATE OR REPLACE FUNCTION public.credit_test_money(p_phone TEXT, p_amount NUMERIC, p_currency TEXT DEFAULT 'CDF')
RETURNS TEXT
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_wallet UUID := test_wallet_of(p_phone);
  v_cents BIGINT := round(p_amount * 100);
  v_balance BIGINT;
BEGIN
  IF v_cents <= 0 THEN RAISE EXCEPTION 'The amount must be positive'; END IF;
  UPDATE wallets SET is_test = true WHERE id = v_wallet AND NOT is_test;
  v_balance := credit_wallet(v_wallet, v_cents, 'ADJUSTMENT', 'TEST-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS'),
    upper(p_currency), jsonb_build_object('source', 'test-money', 'by', current_user));
  RETURN format('Test wallet credited: %s %s (balance %s %s). It can no longer withdraw or send money to a real wallet.',
    p_amount, upper(p_currency), round(v_balance / 100.0, 2), upper(p_currency));
END;
$$ LANGUAGE plpgsql;

-- Takes ALL the money of one currency back from a test wallet.
CREATE OR REPLACE FUNCTION public.remove_test_money(p_phone TEXT, p_currency TEXT DEFAULT 'CDF')
RETURNS TEXT
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_wallet UUID := test_wallet_of(p_phone);
  v_balance BIGINT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM wallets WHERE id = v_wallet AND is_test) THEN
    RAISE EXCEPTION 'This wallet is not a test wallet: its money is real and is not touched';
  END IF;
  v_balance := wallet_balance_cents(v_wallet, upper(p_currency));
  IF v_balance > 0 THEN
    PERFORM debit_wallet(v_wallet, v_balance, 'ADJUSTMENT', 'TEST-REMOVE-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS'),
      upper(p_currency), jsonb_build_object('source', 'test-money', 'by', current_user));
  END IF;
  RETURN format('%s %s of test money removed.', round(v_balance / 100.0, 2), upper(p_currency));
END;
$$ LANGUAGE plpgsql;

-- Nobody but the database owner (the SQL editor) may call these: not the API (service_role), not a user.
REVOKE ALL ON FUNCTION public.test_wallet_of(TEXT) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.credit_test_money(TEXT, NUMERIC, TEXT) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.remove_test_money(TEXT, TEXT) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.wallet_balance_cents(UUID, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.forbid_test_wallet_withdrawal() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.forbid_test_money_to_real_wallet() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.keep_test_wallet_marked() FROM PUBLIC;

-- ============================================================================
-- 070_expense_pro_payment_method.sql
-- ============================================================================
-- ============================================================================
-- 070_expense_pro_payment_method.sql — The Pro subscription is paid by Mobile Money (FlexPaie).
--
-- expense_pro_payments.payment_method used the value 'cinetpay' for "paid through the payment provider", a
-- provider ScanLinkPay does not use. It becomes 'mobile_money' (psp_provider still says which provider).
--
-- Run once in the Supabase SQL editor (after 069), BEFORE deploying the API version that writes 'mobile_money'.
-- ============================================================================

DO $$
DECLARE
  c TEXT;
BEGIN
  FOR c IN
    SELECT con.conname FROM pg_constraint con
      JOIN pg_attribute att ON att.attrelid = con.conrelid AND att.attnum = ANY (con.conkey)
     WHERE con.conrelid = 'public.expense_pro_payments'::regclass AND con.contype = 'c' AND att.attname = 'payment_method'
  LOOP
    EXECUTE format('ALTER TABLE public.expense_pro_payments DROP CONSTRAINT %I', c);
  END LOOP;
END $$;

UPDATE expense_pro_payments SET payment_method = 'mobile_money' WHERE payment_method = 'cinetpay';

ALTER TABLE expense_pro_payments
  ADD CONSTRAINT expense_pro_payments_payment_method_check CHECK (payment_method IN ('wallet', 'mobile_money'));

-- ============================================================================
-- 071_platform_environment.sql
-- ============================================================================
-- ============================================================================
-- 071_platform_environment.sql — Each database says whether it is PRODUCTION or TEST, for good.
--
-- Two Supabase projects: "LinkPay" (production, real customers, real money) and "LinkPay Test" (developers,
-- test money only). This one-row table says which one a database is, and can never be changed afterwards:
--   - production: test money is impossible (credit_test_money refuses);
--   - test: the API refuses every real payment (no FlexPaie money can land in a test database), and test money
--     is written with credit_test_money (docs/BASE_TEST.md).
--
-- Run in the production SQL editor as usual: with nothing else said, the database is marked PRODUCTION.
-- The test database is built with supabase/base_complete.sql, which says TEST before this migration runs.
-- ============================================================================

CREATE TABLE IF NOT EXISTS platform_environment (
  singleton BOOLEAN PRIMARY KEY DEFAULT true CHECK (singleton),
  name TEXT NOT NULL CHECK (name IN ('production', 'test')),
  marked_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO platform_environment (name)
VALUES (CASE WHEN current_setting('linkpay.environment', true) = 'test' THEN 'test' ELSE 'production' END)
ON CONFLICT (singleton) DO NOTHING;

-- Marked once, never changed: a production database can never be turned into a "test" one to mint money.
CREATE OR REPLACE FUNCTION public.platform_environment_is_final()
RETURNS TRIGGER
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RAISE EXCEPTION 'PLATFORM_ENVIRONMENT_FINAL: this database is % for good', OLD.name;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_platform_environment_final ON platform_environment;
CREATE TRIGGER trg_platform_environment_final
  BEFORE UPDATE OR DELETE ON platform_environment
  FOR EACH ROW EXECUTE FUNCTION public.platform_environment_is_final();

ALTER TABLE platform_environment ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON platform_environment FROM PUBLIC, anon, authenticated;
GRANT SELECT ON platform_environment TO service_role;
REVOKE ALL ON FUNCTION public.platform_environment_is_final() FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.is_test_database()
RETURNS BOOLEAN
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE((SELECT name = 'test' FROM platform_environment), false);
$$ LANGUAGE sql STABLE;
REVOKE ALL ON FUNCTION public.is_test_database() FROM PUBLIC, anon, authenticated;

-- Test money exists only in the test database (replaces 069's version, same signature).
CREATE OR REPLACE FUNCTION public.credit_test_money(p_phone TEXT, p_amount NUMERIC, p_currency TEXT DEFAULT 'CDF')
RETURNS TEXT
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_wallet UUID;
  v_cents BIGINT := round(p_amount * 100);
  v_balance BIGINT;
BEGIN
  IF NOT is_test_database() THEN
    RAISE EXCEPTION 'TEST_MONEY_PRODUCTION: this is the PRODUCTION database — test money only exists in LinkPay Test';
  END IF;
  v_wallet := test_wallet_of(p_phone);
  IF v_cents <= 0 THEN RAISE EXCEPTION 'The amount must be positive'; END IF;
  UPDATE wallets SET is_test = true WHERE id = v_wallet AND NOT is_test;
  v_balance := credit_wallet(v_wallet, v_cents, 'ADJUSTMENT', 'TEST-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS'),
    upper(p_currency), jsonb_build_object('source', 'test-money', 'by', current_user));
  RETURN format('Test wallet credited: %s %s (balance %s %s). It can no longer withdraw or send money to a real wallet.',
    p_amount, upper(p_currency), round(v_balance / 100.0, 2), upper(p_currency));
END;
$$ LANGUAGE plpgsql;
REVOKE ALL ON FUNCTION public.credit_test_money(TEXT, NUMERIC, TEXT) FROM PUBLIC, anon, authenticated, service_role;

-- ============================================================================
-- 072_indicative_exchange_rate.sql
-- ============================================================================
-- ============================================================================
-- 072_indicative_exchange_rate.sql — An indicative CDF/USD rate, set by the super admin.
--
-- Shown only as a hint under an amount ("≈ 5,12 $US" on the send screen). It NEVER converts money: CDF and USD
-- stay two independent balances, every amount is debited and credited in its own currency.
-- NULL = not set: the app shows no conversion.
--
-- Run in the Supabase SQL editor (LinkPay Test first, then production), after 071.
-- ============================================================================

ALTER TABLE platform_settings ADD COLUMN IF NOT EXISTS cdf_per_usd NUMERIC(12, 2)
  CHECK (cdf_per_usd IS NULL OR (cdf_per_usd > 0 AND cdf_per_usd < 1000000));

-- ============================================================================
-- 073_offline_expense_entries.sql
-- ============================================================================
-- 073 — "Mes dépenses" usable without network.
-- An expense noted offline waits on the phone and is sent when the network comes back. It carries an id made on the
-- phone (client_ref): if the same note reaches the server twice (answer lost, app closed mid-send), the second one
-- returns the first instead of creating a duplicate. Re-runnable.

ALTER TABLE expense_entries ADD COLUMN IF NOT EXISTS client_ref UUID;

CREATE UNIQUE INDEX IF NOT EXISTS expense_entries_user_client_ref
  ON expense_entries (user_id, client_ref)
  WHERE client_ref IS NOT NULL;

-- ============================================================================
-- 074_offline_pos_sales.sql
-- ============================================================================
-- 074 — The till and the stock keep working without network.
--
-- A sale made offline is paid in cash on the spot (the customer leaves with the goods), kept on the device, and sent
-- later in one piece: record_offline_pos_sale() writes the ticket, its lines, the cash payment and the stock
-- deduction in ONE transaction. Rules:
--   * once: the device's id (client_ref) is unique per shop — the same sale sent twice returns the first;
--   * the money wins: the sale is always recorded at the price the customer paid. What the device could not know is
--     reported, never refused: a price changed meanwhile, a stock already sold by another till (the deduction stops
--     at zero and the missing units are listed for the inventory), a cash session already closed;
--   * the sale keeps its real time (sold_at), within the last 7 days, never in the future.
-- Stock movements made offline (reception, exit, adjustment) also carry a client_ref, kept once.
-- Re-runnable.

ALTER TABLE pos_tickets ADD COLUMN IF NOT EXISTS client_ref UUID;
ALTER TABLE pos_tickets ADD COLUMN IF NOT EXISTS recorded_offline BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE pos_tickets ADD COLUMN IF NOT EXISTS offline_conflicts JSONB;
CREATE UNIQUE INDEX IF NOT EXISTS pos_tickets_merchant_client_ref
  ON pos_tickets (merchant_id, client_ref) WHERE client_ref IS NOT NULL;

ALTER TABLE stock_movements ADD COLUMN IF NOT EXISTS client_ref UUID;
CREATE UNIQUE INDEX IF NOT EXISTS stock_movements_merchant_client_ref
  ON stock_movements (merchant_id, client_ref) WHERE client_ref IS NOT NULL;

CREATE OR REPLACE FUNCTION public.record_offline_pos_sale(
  p_merchant_id UUID,
  p_cashier_id UUID,
  p_client_ref UUID,
  p_currency TEXT,
  p_sold_at TIMESTAMPTZ,
  p_items JSONB,          -- [{ "stock_item_id": uuid, "quantity": int, "unit_price_cents": int }]
  p_received_cents BIGINT
) RETURNS JSONB
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_existing pos_tickets;
  v_session cash_register_sessions;
  v_ticket_id UUID;
  v_number BIGINT;
  v_rate NUMERIC;
  v_line JSONB;
  v_item stock_items;
  v_qty INT;
  v_price BIGINT;
  v_take INT;
  v_total BIGINT := 0;
  v_tva BIGINT;
  v_conflicts JSONB := '[]'::jsonb;
  v_sold_at TIMESTAMPTZ;
BEGIN
  -- Already received (answer lost, sent again): give back the first one.
  SELECT * INTO v_existing FROM pos_tickets WHERE merchant_id = p_merchant_id AND client_ref = p_client_ref;
  IF FOUND THEN
    RETURN jsonb_build_object('ticket_id', v_existing.id, 'created', false, 'conflicts', COALESCE(v_existing.offline_conflicts, '[]'::jsonb));
  END IF;

  IF p_currency NOT IN ('CDF', 'USD') THEN RAISE EXCEPTION 'POS_OFFLINE_BAD_CURRENCY'; END IF;
  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'POS_OFFLINE_EMPTY'; END IF;

  v_sold_at := LEAST(GREATEST(COALESCE(p_sold_at, NOW()), NOW() - INTERVAL '7 days'), NOW());

  -- The session that was open when the sale was made; if it was closed since, the last one of that currency.
  SELECT * INTO v_session FROM cash_register_sessions
    WHERE merchant_id = p_merchant_id AND currency = p_currency AND status = 'open'
    ORDER BY opened_at DESC LIMIT 1;
  IF NOT FOUND THEN
    SELECT * INTO v_session FROM cash_register_sessions
      WHERE merchant_id = p_merchant_id AND currency = p_currency AND opened_at <= v_sold_at
      ORDER BY opened_at DESC LIMIT 1;
    IF NOT FOUND THEN
      SELECT * INTO v_session FROM cash_register_sessions
        WHERE merchant_id = p_merchant_id AND currency = p_currency
        ORDER BY opened_at DESC LIMIT 1;
    END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'POS_OFFLINE_NO_SESSION'; END IF;
    v_conflicts := v_conflicts || jsonb_build_object('type', 'session_closed', 'session_id', v_session.id);
  END IF;

  SELECT COALESCE(pos_tva_rate_pct, 0) INTO v_rate FROM merchants WHERE id = p_merchant_id;
  v_number := public.next_pos_ticket_number(p_merchant_id);

  INSERT INTO pos_tickets (merchant_id, cashier_user_id, cash_register_session_id, status, currency, ticket_number,
                           client_ref, recorded_offline, created_at, updated_at)
  VALUES (p_merchant_id, p_cashier_id, v_session.id, 'open', p_currency, v_number, p_client_ref, TRUE, v_sold_at, NOW())
  RETURNING id INTO v_ticket_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_qty := (v_line->>'quantity')::INT;
    v_price := (v_line->>'unit_price_cents')::BIGINT;
    IF v_qty IS NULL OR v_qty <= 0 OR v_price IS NULL OR v_price < 0 THEN RAISE EXCEPTION 'POS_OFFLINE_BAD_LINE'; END IF;

    SELECT * INTO v_item FROM stock_items
      WHERE id = (v_line->>'stock_item_id')::UUID AND merchant_id = p_merchant_id
      FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'POS_OFFLINE_ITEM_NOT_FOUND:%', v_line->>'stock_item_id'; END IF;
    IF v_item.currency <> p_currency THEN RAISE EXCEPTION 'POS_OFFLINE_ITEM_CURRENCY:%', v_item.name; END IF;

    INSERT INTO pos_ticket_items (ticket_id, stock_item_id, product_name_snapshot, quantity, unit_price_cents_snapshot,
                                  cost_price_cents_snapshot, line_total_cents, created_at)
    VALUES (v_ticket_id, v_item.id, v_item.name, v_qty, v_price, v_item.cost_price_cents, v_price * v_qty, v_sold_at);
    v_total := v_total + v_price * v_qty;

    IF v_price <> v_item.unit_price_cents THEN
      v_conflicts := v_conflicts || jsonb_build_object('type', 'price_changed', 'stock_item_id', v_item.id, 'name', v_item.name,
                                                       'sold_cents', v_price, 'current_cents', v_item.unit_price_cents);
    END IF;

    -- The stock never goes below zero: what another till already sold is listed for the inventory.
    v_take := LEAST(v_qty, GREATEST(v_item.quantity, 0));
    IF v_take > 0 THEN
      INSERT INTO stock_movements (stock_item_id, merchant_id, type, quantity_delta, reason, created_by, created_at)
      VALUES (v_item.id, p_merchant_id, 'sale', -v_take, 'Vente hors ligne ticket #' || v_number, p_cashier_id, v_sold_at);
    END IF;
    IF v_take < v_qty THEN
      v_conflicts := v_conflicts || jsonb_build_object('type', 'stock_short', 'stock_item_id', v_item.id, 'name', v_item.name,
                                                       'sold', v_qty, 'deducted', v_take);
    END IF;
  END LOOP;

  v_tva := CASE WHEN v_rate > 0 THEN ROUND(v_total * v_rate / (100 + v_rate)) ELSE 0 END;

  UPDATE pos_tickets SET subtotal_cents = v_total - v_tva, tva_cents = v_tva, total_cents = v_total WHERE id = v_ticket_id;

  IF v_total > 0 THEN
    INSERT INTO pos_ticket_payments (ticket_id, method, amount_cents, received_cents, status, created_by, created_at)
    VALUES (v_ticket_id, 'cash', v_total, GREATEST(COALESCE(p_received_cents, v_total), v_total), 'confirmed', p_cashier_id, v_sold_at);
  END IF;

  UPDATE pos_tickets
    SET status = 'paid', payment_method = 'cash', paid_at = v_sold_at, updated_at = NOW(),
        offline_conflicts = CASE WHEN jsonb_array_length(v_conflicts) > 0 THEN v_conflicts ELSE NULL END
    WHERE id = v_ticket_id;

  RETURN jsonb_build_object('ticket_id', v_ticket_id, 'created', true, 'conflicts', v_conflicts);
EXCEPTION
  -- Two sends of the same sale crossed: the unique index kept the first one.
  WHEN unique_violation THEN
    SELECT * INTO v_existing FROM pos_tickets WHERE merchant_id = p_merchant_id AND client_ref = p_client_ref;
    IF FOUND THEN
      RETURN jsonb_build_object('ticket_id', v_existing.id, 'created', false, 'conflicts', COALESCE(v_existing.offline_conflicts, '[]'::jsonb));
    END IF;
    RAISE;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.record_offline_pos_sale(UUID, UUID, UUID, TEXT, TIMESTAMPTZ, JSONB, BIGINT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_offline_pos_sale(UUID, UUID, UUID, TEXT, TIMESTAMPTZ, JSONB, BIGINT) TO service_role;

-- ============================================================================
-- 075_offline_org_sales.sql
-- ============================================================================
-- 075 — The "Ventes" module of businesses (shops, electronics…) keeps working without network.
--
-- Same rules as the till (074): a sale made offline is paid in cash on the spot, kept on the device and sent later
-- in one piece. record_offline_org_sale() writes the sale (PAID, cash), its lines with the product sheet frozen at
-- sale time, and the stock exit in ONE transaction, once per client_ref (unique per business). The money wins:
-- a price changed meanwhile or a stock already sold elsewhere is reported (offline_conflicts), never refused; the
-- stock exit stops at zero. Restock requests written offline also carry a client_ref, kept once. Re-runnable.

ALTER TABLE restock_requests ADD COLUMN IF NOT EXISTS client_ref UUID;
CREATE UNIQUE INDEX IF NOT EXISTS restock_requests_merchant_client_ref
  ON restock_requests (merchant_id, client_ref) WHERE client_ref IS NOT NULL;

-- Cash put in / taken out of the till drawer offline (petty expense, deposit): kept once too.
ALTER TABLE cash_movements ADD COLUMN IF NOT EXISTS client_ref UUID;
CREATE UNIQUE INDEX IF NOT EXISTS cash_movements_session_client_ref
  ON cash_movements (session_id, client_ref) WHERE client_ref IS NOT NULL;

ALTER TABLE sales ADD COLUMN IF NOT EXISTS client_ref UUID;
ALTER TABLE sales ADD COLUMN IF NOT EXISTS recorded_offline BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE sales ADD COLUMN IF NOT EXISTS offline_conflicts JSONB;
CREATE UNIQUE INDEX IF NOT EXISTS sales_org_client_ref
  ON sales (organization_id, client_ref) WHERE client_ref IS NOT NULL;

CREATE OR REPLACE FUNCTION public.record_offline_org_sale(
  p_org_id UUID,
  p_merchant_id UUID,
  p_seller_id UUID,
  p_client_ref UUID,
  p_sold_at TIMESTAMPTZ,
  p_items JSONB          -- [{ "stock_item_id": uuid, "quantity": int, "unit_price_cents": int }]
) RETURNS JSONB
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_existing sales;
  v_sale_id UUID;
  v_reference TEXT;
  v_line JSONB;
  v_item stock_items;
  v_qty INT;
  v_price BIGINT;
  v_take INT;
  v_total BIGINT := 0;
  v_currency TEXT := NULL;
  v_conflicts JSONB := '[]'::jsonb;
  v_sold_at TIMESTAMPTZ;
BEGIN
  SELECT * INTO v_existing FROM sales WHERE organization_id = p_org_id AND client_ref = p_client_ref;
  IF FOUND THEN
    RETURN jsonb_build_object('sale_id', v_existing.id, 'created', false, 'conflicts', COALESCE(v_existing.offline_conflicts, '[]'::jsonb));
  END IF;

  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'SALE_OFFLINE_EMPTY'; END IF;
  PERFORM 1 FROM merchants WHERE id = p_merchant_id AND organization_id = p_org_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'SALE_OFFLINE_BAD_STATION'; END IF;

  v_sold_at := LEAST(GREATEST(COALESCE(p_sold_at, NOW()), NOW() - INTERVAL '7 days'), NOW());
  -- Readable and unique: SALE-HL-<16 hex of the device id> (64 random bits).
  v_reference := 'SALE-HL-' || UPPER(SUBSTRING(REPLACE(p_client_ref::text, '-', '') FROM 1 FOR 16));

  INSERT INTO sales (organization_id, merchant_id, reference, status, payment_method, currency, total_cents,
                     created_by, paid_at, created_at, updated_at, client_ref, recorded_offline)
  VALUES (p_org_id, p_merchant_id, v_reference, 'PAID', 'cash', 'CDF', 0, p_seller_id, v_sold_at, v_sold_at, NOW(),
          p_client_ref, TRUE)
  RETURNING id INTO v_sale_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_qty := (v_line->>'quantity')::INT;
    v_price := (v_line->>'unit_price_cents')::BIGINT;
    IF v_qty IS NULL OR v_qty <= 0 OR v_price IS NULL OR v_price < 0 THEN RAISE EXCEPTION 'SALE_OFFLINE_BAD_LINE'; END IF;

    SELECT * INTO v_item FROM stock_items
      WHERE id = (v_line->>'stock_item_id')::UUID AND merchant_id = p_merchant_id
      FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'SALE_OFFLINE_ITEM_NOT_FOUND:%', v_line->>'stock_item_id'; END IF;
    IF v_currency IS NOT NULL AND v_currency <> v_item.currency THEN RAISE EXCEPTION 'SALE_OFFLINE_MIXED_CURRENCY'; END IF;
    v_currency := v_item.currency;

    INSERT INTO sale_items (sale_id, stock_item_id, name, category, quantity, unit_price_cents, unit_cost_cents, currency, details, created_at)
    VALUES (v_sale_id, v_item.id, v_item.name, v_item.category, v_qty, v_price, COALESCE(v_item.cost_price_cents, 0), v_item.currency,
            jsonb_build_object('brand', v_item.brand, 'model', v_item.model, 'condition', v_item.condition,
                               'serial_number', v_item.serial_number, 'warranty_months', v_item.warranty_months,
                               'attributes', COALESCE(v_item.attributes, '{}'::jsonb)),
            v_sold_at);
    v_total := v_total + v_price * v_qty;

    IF v_price <> v_item.unit_price_cents THEN
      v_conflicts := v_conflicts || jsonb_build_object('type', 'price_changed', 'stock_item_id', v_item.id, 'name', v_item.name,
                                                       'sold_cents', v_price, 'current_cents', v_item.unit_price_cents);
    END IF;

    v_take := LEAST(v_qty, GREATEST(v_item.quantity, 0));
    IF v_take > 0 THEN
      INSERT INTO stock_movements (stock_item_id, merchant_id, type, quantity_delta, reason, created_by, created_at)
      VALUES (v_item.id, p_merchant_id, 'out', -v_take, 'Vente hors ligne ' || v_reference, p_seller_id, v_sold_at);
    END IF;
    IF v_take < v_qty THEN
      v_conflicts := v_conflicts || jsonb_build_object('type', 'stock_short', 'stock_item_id', v_item.id, 'name', v_item.name,
                                                       'sold', v_qty, 'deducted', v_take);
    END IF;
  END LOOP;

  UPDATE sales
    SET currency = COALESCE(v_currency, 'CDF'), total_cents = v_total,
        offline_conflicts = CASE WHEN jsonb_array_length(v_conflicts) > 0 THEN v_conflicts ELSE NULL END
    WHERE id = v_sale_id;

  RETURN jsonb_build_object('sale_id', v_sale_id, 'created', true, 'conflicts', v_conflicts, 'reference', v_reference);
EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_existing FROM sales WHERE organization_id = p_org_id AND client_ref = p_client_ref;
    IF FOUND THEN
      RETURN jsonb_build_object('sale_id', v_existing.id, 'created', false, 'conflicts', COALESCE(v_existing.offline_conflicts, '[]'::jsonb));
    END IF;
    RAISE;
END;
$$ LANGUAGE plpgsql;

REVOKE ALL ON FUNCTION public.record_offline_org_sale(UUID, UUID, UUID, UUID, TIMESTAMPTZ, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_offline_org_sale(UUID, UUID, UUID, UUID, TIMESTAMPTZ, JSONB) TO service_role;

-- ============================================================================
-- 076_merge_food_into_supermarket.sql
-- ============================================================================
-- 076 — One sector for supermarkets and food shops.
--
-- "Alimentation" was a third sector next to "Supermarché" and "Électronique": food shops then sold through the Ventes
-- module, without the till. A food shop works like a supermarket (same till, same thermal ticket, same aisles), so the
-- two become one: 'supermarche'. Electronics stays apart (IMEI, serial number, warranty).
-- A supermarket has no "vendeur" (the cashier sells and takes the money): the vendeurs of these businesses become
-- caissiers, on the same station. Their new role applies at their next sign-in. Re-runnable.

UPDATE user_roles ur
   SET role_id = (SELECT id FROM roles WHERE slug = 'caissier')
 WHERE ur.role_id = (SELECT id FROM roles WHERE slug = 'vendeur')
   AND ur.organization_id IN (SELECT id FROM organizations WHERE sector = 'alimentation');

UPDATE organizations SET sector = 'supermarche' WHERE sector = 'alimentation';

-- ============================================================================
-- 077_one_seller_role.sql
-- ============================================================================
-- 077 — One person sells and takes the money.
--
-- In our shops the seller is also the cashier: there is a single sales role, « Vendeur / caissier » (slug 'caissier',
-- the one the till, the cash register and the Ventes module already accept), in supermarkets and electronics shops
-- alike. The remaining vendeurs become caissiers on the same station; the new role applies at their next sign-in
-- (until then the API still accepts 'vendeur'). Re-runnable.

UPDATE user_roles
   SET role_id = (SELECT id FROM roles WHERE slug = 'caissier')
 WHERE role_id = (SELECT id FROM roles WHERE slug = 'vendeur')
   AND organization_id IS NOT NULL;

UPDATE roles SET name = 'Vendeur / caissier', description = 'Vend, encaisse et imprime le ticket d''une entreprise'
 WHERE slug = 'caissier';

-- ============================================================================
-- 078_merchant_invitations.sql
-- ============================================================================
-- 078 — A cashier joins a shop only if they accept.
--
-- A shop owner used to add a cashier by email and the person's account became a cashier at once, without being asked
-- or told. With the phone number as well (much easier to know than an email), anybody could have turned someone's
-- account into their cashier. Now the owner sends an INVITATION (by phone or email); the person sees it in their app
-- and accepts or refuses; nothing changes on their account until they accept. The owner can cancel it while it waits.
-- An invitation not answered within 7 days lapses. Re-runnable.

CREATE TABLE IF NOT EXISTS merchant_invitations (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  merchant_id UUID NOT NULL REFERENCES merchants(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  invited_by UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  status VARCHAR(20) NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'accepted', 'declined', 'cancelled', 'expired')),
  expires_at TIMESTAMPTZ NOT NULL DEFAULT (NOW() + INTERVAL '7 days'),
  responded_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- One invitation waiting per shop and person.
CREATE UNIQUE INDEX IF NOT EXISTS merchant_invitations_one_pending
  ON merchant_invitations (merchant_id, user_id) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS merchant_invitations_user ON merchant_invitations (user_id, status);

-- Only the API (service role) reads and writes it.
ALTER TABLE merchant_invitations ENABLE ROW LEVEL SECURITY;

-- ============================================================================
-- 079_treasury.sql
-- ============================================================================
-- 079 — Trésorerie: what ScanLinkPay may take out of its FlexPaie account without touching anybody's money.
--
-- The real money sits on ScanLinkPay's FlexPaie merchant account. Part of it belongs to the users: every balance
-- (wallets, savings), every withdrawal debited but not sent yet, every payment received for a shop and not yet
-- credited to it. What is left is ScanLinkPay's own money (subscriptions, commissions, fees).
-- treasury_overview() computes, per currency, what is owed and what was earned (test wallets left out);
-- treasury_balances keeps the FlexPaie balance the super admin reads in the FlexPaie dashboard and types in (no
-- FlexPaie API is used for it). The page subtracts one from the other. Re-runnable.

CREATE TABLE IF NOT EXISTS treasury_balances (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  currency VARCHAR(3) NOT NULL CHECK (currency IN ('CDF', 'USD')),
  amount_cents BIGINT NOT NULL CHECK (amount_cents >= 0),
  note TEXT,
  noted_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  noted_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS treasury_balances_latest ON treasury_balances (currency, noted_at DESC);
ALTER TABLE treasury_balances ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.treasury_overview()
RETURNS TABLE (
  currency VARCHAR,
  owed_wallets BIGINT,          -- every positive wallet balance (what each account could withdraw)
  owed_savings BIGINT,          -- money put aside in savings pots
  pending_withdrawals BIGINT,   -- debited from a wallet, not sent yet
  uncredited_payments BIGINT,   -- paid to a shop, not credited to its wallet yet (the retry job does it)
  negative_wallets INT,         -- wallets below zero: an anomaly to look at
  subscriptions BIGINT,         -- earned: business subscriptions
  commissions BIGINT,           -- earned: ScanLinkPay's commission on payments
  withdrawal_fees BIGINT,       -- earned: fees on withdrawals sent
  transfer_fees BIGINT,         -- earned: fees on transfers
  pro_payments BIGINT           -- earned: "Mes dépenses" Pro plan (paid by Mobile Money)
)
SECURITY DEFINER
SET search_path = public
AS $$
  WITH cur(c) AS (VALUES ('CDF'::varchar), ('USD'::varchar)),
  real_wallets AS (SELECT id, user_id FROM wallets WHERE NOT is_test),
  bal AS (
    SELECT le.currency, le.wallet_id,
           SUM(CASE WHEN le.direction = 'credit' THEN le.amount_cents ELSE -le.amount_cents END) AS b
      FROM ledger_entries le JOIN real_wallets w ON w.id = le.wallet_id
     GROUP BY le.currency, le.wallet_id
  )
  SELECT cur.c,
    COALESCE((SELECT SUM(b) FROM bal WHERE bal.currency = cur.c AND b > 0), 0)::BIGINT,
    COALESCE((SELECT SUM(CASE WHEN e.type = 'round_up' THEN e.amount_cents ELSE -e.amount_cents END)
                FROM savings_pot_entries e JOIN savings_pots p ON p.id = e.pot_id
               WHERE p.currency = cur.c AND p.user_id IN (SELECT user_id FROM real_wallets)), 0)::BIGINT,
    COALESCE((SELECT SUM(wd.amount_cents) FROM withdrawals wd JOIN real_wallets w ON w.id = wd.wallet_id
               WHERE wd.currency = cur.c AND wd.status IN ('PENDING', 'PROCESSING')), 0)::BIGINT,
    COALESCE((SELECT SUM(t.net_cents) FROM transactions t
               WHERE t.currency = cur.c AND t.status IN ('SUCCESS', 'PARTIALLY_REFUNDED') AND t.wallet_credited_at IS NULL), 0)::BIGINT,
    (SELECT COUNT(*) FROM bal WHERE bal.currency = cur.c AND b < 0)::INT,
    COALESCE((SELECT SUM(sp.amount_cents) FROM subscription_purchases sp
               WHERE sp.currency = cur.c AND sp.purchased_by IN (SELECT user_id FROM real_wallets)), 0)::BIGINT,
    COALESCE((SELECT SUM(t.platform_fee_cents) FROM transactions t
               WHERE t.currency = cur.c AND t.status IN ('SUCCESS', 'PARTIALLY_REFUNDED')), 0)::BIGINT,
    COALESCE((SELECT SUM(wd.fee_cents) FROM withdrawals wd JOIN real_wallets w ON w.id = wd.wallet_id
               WHERE wd.currency = cur.c AND wd.status = 'SUCCESS'), 0)::BIGINT,
    COALESCE((SELECT SUM(tr.fee_cents) FROM transfers tr JOIN real_wallets w ON w.id = tr.sender_wallet_id
               WHERE tr.currency = cur.c AND tr.status = 'SUCCESS'), 0)::BIGINT,
    COALESCE((SELECT SUM(pp.amount_cents) FROM expense_pro_payments pp
               WHERE pp.currency = cur.c AND pp.status = 'SUCCESS'), 0)::BIGINT
  FROM cur
$$ LANGUAGE sql STABLE;

REVOKE ALL ON FUNCTION public.treasury_overview() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.treasury_overview() TO service_role;

